import{A as e}from"./index-tdrS2Zvt.js";const t={adv_g561_wenlu:{id:"adv_g561_wenlu",title:"驿站来了个只问不答的独臂客",mother:"M7",channel:"T1",rarity:2,entry:{node:"yh_yizhan",chance:.13},stages:[{xinglu:"是岁驿站逢独臂客。独臂客的话糙，理却直——「我问了一辈子——问出来的东西，比读出来的多。」",text:"独臂客坐在一块画着地图的旧木板旁，见谁都想问两句——问得认真，听得也认真。「你说人为什么要问路？」独臂客自问自答，「因为路认生。认生的东西，你不问它，它就骗你——这是路教的，我只是转述。」独臂客看着你：「客人，我问你——你这一路，是奔着什么来的？别急着答，想清楚再说。」",options:[{label:"「我想清楚再答。」",goto:1,effect:void 0},{label:"「怪人一个，不理也罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「怪人就怪人。」独臂客笑呵呵的，「驿站人人都这么叫。可你也看见了——他们路过还是要看一眼我那牌子。为什么？怪话里头，偶尔藏着正经。人不能全信怪人，可也不能一个怪人都不信——全信了傻，全不信了苦。你自己掂量。」他冲你摆摆手，继续挂他的问题。"}}]},{xinglu:"是岁驿站一课。独臂客把话说到根上——「问路的人最聪明——他省下的冤枉路，就是他的学问。」",text:"「我最得意的一个问题，」独臂客压低了声音，「救过一个人。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」独臂客缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」独臂客笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」独臂客把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「这问题，我收下了。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"恩",text:"听独臂客讲哑巴师父的沙地问句，学会「看还是觉得」"},text_after:"「看，还是觉得——这一句你带走了。」独臂客满意地送你出门。后来你在生意上、恩怨里、抉择前，无数次问自己这一句。它不能替你做对的事——可它让你少做了许多自以为对的事。你从此逢人便传这句话，传的时候都说是从一个怪老头那儿听来的。"}},{label:"「我从不问路，只看脚下的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「从不问路？」独臂客看着你，忽然认真了，「客人，我不拦你。可我送你一句话：不问路的人，不是路盲——是路盲里胆子最大的。老天爷不在乎你问不问，它只管把你引到岔路口。你凭本事闯，闯对了是命大，闯错了——」他顿了顿，「没有人给你收尸。走吧。这话搁这儿，你哪天想起，算我的。」"}}]}]},adv_g562_jizhang:{id:"adv_g562_jizhang",title:"路遇妇人——在平安号镖局分号替人情记着账",mother:"M8",channel:"T2",rarity:1,entry:{node:"yh_biaoju",chance:.06},stages:[{xinglu:"是岁平安号镖局分号逢妇人。妇人的话糙，理却直——「情分这东西，不记账就散——散了再聚，就生分了。」",text:"平安号镖局分号里，妇人守着一串打了结记事的旧麻绳，谁家有笔说不清的旧账，都来问他。「有人问我，死人欠的账记来做什么。」妇人说，「记。儿子长大来翻账——看见他爹当年受过谁的恩、还过谁的债，他就知道自己是个什么根底。账本就是家谱，还是最老实的那一页。」「帮我断个案子。」妇人把两个争执的人拉到一处，「他们都信你外乡人嘴严。」",options:[{label:"「报个名姓，帮我翻翻。」",goto:1,effect:void 0},{label:"「你这行当，多管闲事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过去？」妇人摇头，「过得去的才叫过去。过不去的，你不理它，它就长在心里长成疙瘩。我这柜子里的账，一半是让人过得去的——账面摆出来，多少年的疙瘩，一句话就解了。」"}}]},{xinglu:"是岁平安号镖局分号一课。妇人把话说到根上——「一笔账两头记——欠的人记着还，还的人记着情，两头都记着，人就亲了。」",text:"「你见过两家人为一笔账断了二十年的来往么？」妇人说，「我接手过。」「师父考我的是：背错一笔账给我听。」妇人说，「我背了，背得一丝不差。他摇头说：你背的是字。他要的是我记错一笔——然后自己心疼。他说，不心疼账的记账人，记的是死数；心疼账的，记的才是人情。」妇人摩挲着账本，「我后来真记错过一回——心疼得半宿睡不着。从那晚起，我才算入了行。」「替我记一笔。」妇人忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「它开着门，我就放心。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"恩",text:"在平安号镖局分号受妇人一句账理：欠的记着，还的记着"},text_after:"你把那句话带走了。后来你受了人的恩，总会想起那笔「不欠谁的」的账——想起时脸就发热，热完了就认真去还。再后来你也学着记：谁帮过你、你欠过谁，一笔一笔记在心里。你还真把这些教给了你的孩子——账本没传下去，账理传下去了。"}},{label:"「人情最靠不住，你记了也白记。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」妇人笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g563_shouwu:{id:"adv_g563_shouwu",title:"城隍庙的一课：盲眼老者守着一件旧物",mother:"M5",channel:"T3",rarity:2,entry:{node:"yh_chenghuang",chance:.1},stages:[{xinglu:"是岁城隍庙逢盲眼老者。盲眼老者的话糙，理却直——「东西没了可以再造，守的规矩断了就接不上。」",text:"盲眼老者见了你，头一句就是：「别嫌它旧。」说的是一座路边义亭。盲眼老者说守这东西有讲究：「每天来看一眼，缺了补，脏了擦。不为别的——它要是哪天塌了，方圆几十里的人，心里都得空一块。」「帮我看看它哪儿不对。」盲眼老者退开半步，「外人一眼看出来的毛病，守的人反而看不见。」",options:[{label:"坐下陪盲眼老者说说话",goto:1,effect:void 0},{label:"「这种闲事，与我何干。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」盲眼老者不恼反笑，「天下的正经事，起头都是闲事。守桥的、修路的、点灯的——起初谁不说他们闲？」你走远了，那句「闲事」在你耳朵里转了一路，越转越不像闲事。"}}]},{xinglu:"是岁城隍庙一课。盲眼老者把话说到根上——「守的年头久了，它就是家。」",text:"盲眼老者从一座路边义亭底下摸出个旧物件：「这是上一任守物人留下的。你看看——守物的人，都给后来人留话。」「师父留的那句话，我琢磨了二十年。」盲眼老者说，「他写的是：守到你觉得是它在守你，才算入门。我当时不懂——现在懂了。它站在这儿，我就不敢倒下。」「守物人不说谢。」盲眼老者说，「你要真帮了它，它自己会谢你——哪天你落难了，想起这世上有一处地方，有个东西好好站着——你就暖和了。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"义",text:"与盲眼老者共守一座路边义亭一夜，学会守物的规矩"},text_after:"你把来处和去处都念了。念完盲眼老者笑得眼睛眯成一条缝：「好了，你们认识了。往后你不管走多远，它都算你认识的东西——人这辈子，认识的东西多了，心里就宽。」"}},{label:"「这话太重，我不敢当。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」盲眼老者点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g564_chuanyi:{id:"adv_g564_chuanyi",title:"在车马行，把手艺往下传的中年汉子",mother:"M3",channel:"T1",rarity:2,entry:{node:"yh_chemahang",chance:.06},stages:[{xinglu:"是岁车马行逢中年汉子。中年汉子的话糙，理却直——「手艺人的坟头不用碑——他的手艺活在别人手上，就是碑。」",text:"车马行里，中年汉子正带着徒弟做活，手里是一台吱呀作响的老纺车，一招一式都极稳。中年汉子说这行最金贵的不是手艺，是规矩：「什么料配什么工、什么活收什么价——规矩乱了，手艺就散了。」「你要是感兴趣，我讲细点。」中年汉子说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"站过去看您做活",goto:1,effect:void 0},{label:"「学这个能挣几个钱？」",end:!0,effect:{stat:{wuxing:1},text_after:"「急事要紧，去忙吧。」中年汉子摆摆手，忽然又补了一句：「急事里最急的，往往是最不该急的。你路上想想这话。」你出了门越想越不是味儿——他怎么知道你心里正为一件不该急的事上火？"}}]},{xinglu:"是岁车马行一课。中年汉子把话说到根上——「传艺先传心，心不正，手艺就是凶器。」",text:"中年汉子说起一个走了的徒弟，说到一半停了：「不提了。可你听我讲完——这事跟我这手艺有关。」「师父那幅字写的是：手稳不如心稳。」中年汉子望着墙，「我年轻时觉得这话虚。有一年赶工，我心里乱，手没抖，活却全歪了——那一刻我才懂：手是心的影子。从那天起，我教徒弟先教静心。」中年汉子把一台吱呀作响的老纺车放回原位，郑重其事：「手艺人就说手艺人的话。你今天听的多，能带走一句就够——做什么都行，把手上的活当人看。」",options:[{label:"「谢先生一课。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"恩",text:"看中年汉子带徒一下午，学会「骂是疼」的道理"},text_after:"你站了一下午，看中年汉子带徒弟。收工时他问你看出什么没有。你说：「您骂人的话，跟夸人的话一样多。」他大笑：「对喽！手艺人捧徒弟，是害他；骂徒弟，是疼他。你往后再带人，记住这个理。」"}},{label:"「与我何干，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要绝就绝。」中年汉子淡淡地说，「手艺绝不绝，不看我这代人喊多响——看下代人肯不肯弯腰。我弯了三十年腰了，够了。绝了也不冤：它来的时候有人敬，走的时候有人送，全始全终。」你出门时回头看了一眼，中年汉子已经又坐回一台吱呀作响的老纺车前——绝不绝的话撂在那儿，手上的活一天没停。"}}]}]},adv_g565_haiyuan:{id:"adv_g565_haiyuan",title:"在雁回峡，替故人还愿的妇人",mother:"M4",channel:"T2",rarity:2,entry:{node:"yh_xia",chance:.12},stages:[{xinglu:"是岁雁回峡逢妇人。妇人的话糙，理却直——「还愿的人不问值不值——问值不值的时候，愿就已经不是愿了。」",text:"你见妇人对着一张画了一半的画自言自语，像在跟什么人回话。「家里人劝我，人走了就放下。」妇人摇头，「放下是给活人的宽心话。可愿不是包袱——愿是路标。我把这个愿还了，往后他坟头的草，我看着都顺眼。」妇人忽然问你：「客人识路广——你听过一张画了一半的画的去处么？随便一点线索，我都谢。」",options:[{label:"「这字我还认得。」",goto:1,effect:void 0},{label:"「人都没了，何必呢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」妇人站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁雁回峡一课。妇人把话说到根上——「愿这个东西，许的时候轻飘飘，还的时候千斤重。」",text:"「说起这个愿的来历，」妇人坐下身来，「得从头讲。」「讲一个还愿的故事：有个老猎户，临终托我把他攒的一袋盐分给当年一起守山的弟兄。」妇人说，「弟兄散了，我找了四年，七个找到了六个。第七个，去年在狱里寻着——他犯了事。我把盐给他，他捧着哭了半宿，说：哥几个还记着我。出狱那天，他来找我，如今在山上替人守林。你说，一袋盐值什么？可有些时候，一袋盐就是把人从沟里拉上来的绳。」妇人重新收拾好行囊：「客人的话我记下了。愿还得接着赶路——它等不起，我也不能老。」他冲你拱手，「你若哪天也遇上该还的愿——别拖。拖，是还愿这行唯一的死敌。」",options:[{label:"「您到家了，替他放心。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"帮妇人辨认故人亲笔，愿上缺的一角补齐了"},text_after:"你帮着辨出了那页纸上的字——缺的那一角，是收信人的名字。妇人盯着那个名字看了许久：「对上了。就差这个字，我在县里翻了三天的户籍。」他抬头时眼眶红了，「客人，你今天不是帮我看字——你是替他把最后一句话，送到了门口。」"}},{label:"「这故事听着累。」",end:!0,effect:{stat:{wuxing:1},text_after:"「帮不上不打紧。」妇人摆摆手，「别缠着我——这话就伤人了。我讨的不是你的帮，是你让一步路。让一步路，天塌不下来。」他让到道旁，先请你走。你从他身边过的时候，忽然觉得这一步，让得自己心里发虚。"}}]}]},adv_g566_zengxing:{id:"adv_g566_zengxing",title:"清瘦老者在水门码头白送路上的东西",mother:"M1",channel:"T3",rarity:2,entry:{node:"lj_shuimen",chance:.08},stages:[{xinglu:"是岁水门码头逢清瘦老者。清瘦老者的话糙，理却直——「我送的不是东西，是「有人管你」这句话。」",text:"你打水门码头过，清瘦老者招呼你：「歇歇脚？不要钱，也别推——推就见外了。」「别多想，不是施舍。」清瘦老者把东西推给你，「施舍是人上人下，我这个是递手——你渴了，我这里正好有。就这么简单。」「帮我记个账呗。」清瘦老者递过来一个小本子，「不是记谁拿了什么——是记今天又有几个人用了它。这账好看，你写一笔。」",options:[{label:"「我取一份，谢谢。」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」清瘦老者愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁水门码头一课。清瘦老者把话说到根上——「赠人一程，自己脚下的路也宽了一寸。」",text:"「有人劝我立个碑，写上善人某某。」清瘦老者摇头，「你听听我为什么不立。」「那年来了个贼，夜里偷我的东西不说，还砸了我的牌子。」清瘦老者说，「我第二天照样摆，牌子重写一块，添了四个字：『夜路慢行』。后来那贼又来——这回是白天，红着脸放下一捆柴，一句话没说走了。」清瘦老者呵呵地笑，「你瞧，善这东西不咬人，它泡人。泡久了，铁石心肠也软。」「我老了，这摊子早晚交出去。」清瘦老者望着路，「交给谁？交给先坐下来的那个人。谁肯坐下来陪它过日子，它就是谁的。你哪天路过歇脚——兴许就是你。」",options:[{label:"「路上见，老丈。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"义",text:"受清瘦老者所托，允诺传递路边的规矩"},text_after:"「我可没说一定是我。」你摆手。清瘦老者笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一垛谁都可取的干草边——像路长出来的一部分。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」清瘦老者居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一垛谁都可取的干草像一方小小的印，盖在漫长的路上。"}}]}]},adv_g567_shouye:{id:"adv_g567_shouye",title:"在漕帮总舵，夜里替人醒着的妇人",mother:"M2",channel:"T1",rarity:1,entry:{node:"lj_caobang",chance:.06},stages:[{xinglu:"是岁漕帮总舵逢妇人。妇人的话糙，理却直——「夜里的灯为什么少？因为人都在睡——总得有人替睡的人醒着。」",text:"夜里你到漕帮总舵，妇人提着一段堤坝的巡查路巡到跟前，先给你照了个亮。「白天他们叫我老夜猫子。」妇人嘿嘿地笑，「等你夜里病了、丢了东西、被人堵了——你第一个想起的就是老夜猫子。到那时我就不是夜猫子了，是恩人。人呐，白天夜里两张脸，我两样都见惯了。」「夜深了。」妇人看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「夜里的事，讲讲。」",goto:1,effect:void 0},{label:"「守夜的能有什么出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不用我管？」妇人收了灯，「好，我不管。可我巡到你家墙根，听见里头摔东西——我照旧多站一刻。为什么？我婆娘也摔过。摔东西的人，多半是喊救命喊不出声的。」他把灯转回去，「你家的事我不管——你的命，我夜里路过总得看一眼。」你那一夜睡得极不安稳。"}}]},{xinglu:"是岁漕帮总舵一课。妇人把话说到根上——「夜里的事，白天看不见——看不见不等于没有。」",text:"「你以为守夜就是防贼？」妇人摇头，「夜里的事，十件有九件不是贼。」「官府管不了的事多了。」妇人屈指头数，「两口子半夜吵架要动刀的、孩子高热抽搐的、老人走了没人发现的、外乡人病倒在道旁的——这些都不归谁管，可它们都发生在夜里。」妇人摊摊手，「我管不了天下——我管得了漕帮总舵的夜里。这就够了。」妇人把灯吹熄了——天光已经泛白。「灯不用了。」他说，「灯是夜里的东西。你记住这盏灯照过你——就够了。」",options:[{label:"「保我十年太平。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"听妇人讲砸门四十七扇的旧事，识得守夜人的分寸"},text_after:"天亮了。你按妇人教的走了那条新路——果然避开了塌方段。回头望，妇人已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜漕帮总舵的太平，全是这根梆子敲出来的。"}},{label:"「守夜能守出什么名堂。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」妇人指指自己的眼睛，「我这双眼二十年没睡过一个整觉——漕帮总舵每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g568_shiyi:{id:"adv_g568_shiyi",title:"书院来了个替失物寻主人的少年",mother:"M6",channel:"T2",rarity:1,entry:{node:"lj_shuyuan",chance:.11},stages:[{xinglu:"是岁书院逢少年。少年的话糙，理却直——「世上的失物比失物的人多——总得有人替它们排队等主人。」",text:"少年收着一船漂来的遗物，逢人先问一句「你可认得……」——问了十年，问了满城的摇头。「这一屋子，全是三年没人认的。」少年拍了拍一船漂来的遗物，「按理可以处置了。我不——三年找不到主人，我就再等三年。东西等得起，等不起的是万一哪天，那个找它的人来了，东西没了。」少年忽然问你：「客人一路走来，可曾在别处见过这样的物件？」他把一件失物举到你眼前。",options:[{label:"「我帮你认认。」",goto:1,effect:void 0},{label:"「这行当，没出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人？」少年摇头，「你丢了东西就知道了——丢东西的人，个个都是痴人。我见过丢了亡妻一支簪子的铁塔似的汉子，在我这儿哭成泪人。你笑痴——那是你的福气。真到了痴那天，你盼着世上多几个痴人。」他把门为你拉开，「慢走。愿你一辈子用不上我这行。」"}}]},{xinglu:"是岁书院一课。少年把话说到根上——「遗落的东西不会说话——可它们都在等人。」",text:"「我这里头，最贵的一件东西，」少年指指一船漂来的遗物，「一文钱不值。可它等主人等了十五年。」「认走三回的那位，是个老先生。」少年说，「第一回认走怀表，第二回认走烟斗，第三回又要认走一顶帽子——我留了个心眼，问他东西上有什么记号。他答不上来。」少年叹口气，「不是贼——是痴了的老爷子。他的东西都在儿子那儿，他自个儿记不得，看见像我库里描述的就认。我没拆穿，陪他坐了一下午，听他讲他丢的每一件东西——哪一件背后都是他的老伴儿。后来他儿子来谢我，说老爷子那晚睡了两年来头一个整觉。」少年送你到门口，回身望着满屋一船漂来的遗物：「客人，你笑我守破烂也好，敬我守念想也好——这屋子东西，早晚会一件一件回到人手里。到那时候，我这屋子空了，我这心，也就满了。」",options:[{label:"「这行当，敬您一声。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"义",text:"在书院帮少年归类失物，替七户人家拆了死结"},text_after:"你认出了包袱上的字——是北边某府的馆阁体，还带着军中的写法。「军中的！」少年一拍大腿，「怪不得我在商旅里问不出——我往驿站问去！」他高兴得像捡了宝，拉着你的手直摇：「客人，你这一眼，顶我三个月的腿。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人就痴人。」少年坦然得很，「这世上总得有人痴——都精明着，丢的东西就真没了。你精明你的，我痴我的。哪天你精明不动了、累了，我这一屋子痴，兴许还能给你焐焐手。」"}}]}]},adv_g569_wenlu:{id:"adv_g569_wenlu",title:"城外湖泽里只问不答的清瘦老者",mother:"M7",channel:"T3",rarity:1,entry:{node:"lj_huze",chance:.1},stages:[{xinglu:"是岁城外湖泽逢清瘦老者。清瘦老者的话糙，理却直——「人有答案还问，是心里不踏实；没答案就问，是心里明白。」",text:"清瘦老者坐在一串记事的木牌旁，见谁都想问两句——问得认真，听得也认真。「你说人为什么要问路？」清瘦老者自问自答，「因为路认生。认生的东西，你不问它，它就骗你——这是路教的，我只是转述。」「客人走南闯北，见得多。」清瘦老者凑近了些，「帮我评评，这个问题，问得蠢不蠢？」",options:[{label:"「这个利息，我还。」",goto:1,effect:void 0},{label:"「怪人一个，不理也罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」清瘦老者哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁城外湖泽一课。清瘦老者把话说到根上——「我不教人——我提问题，路让人自己走。」",text:"「我师父是个哑巴。」清瘦老者说这话时屋里静了静，「一辈子没说过一句话——可他教我的，全是问。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」清瘦老者缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」清瘦老者笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」「我送你出门。」清瘦老者边走边说，「记住——路上遇事，先别急着找答案。先问自己一句：这事我是在看，还是在觉得？这一句，顶你半生的学费。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"恩",text:"在清瘦老者店里吵了一架，各自往前挪了半步"},text_after:"你摘走的问题是：「你怕的东西，值得你怕么？」这个问题你在心里盘了一年，最后自己写了个答案寄回去。半年后你路过城外湖泽，看见你的答案被挂上了墙，旁边还有七八张别人还的「利息」。你站在满墙的问句前——那一家小店，原来早成了半条街的心里话。"}},{label:"「我从不问路，只看脚下的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不顶饭吃？」清瘦老者不急不恼，「饭是吃的，问题是活的。光吃饭不想事的人，跟牲口拉磨一个样——磨转得再快，路一寸没走。我不是笑话你——我五十岁之前也是这么活的。」他拍拍一串记事的木牌，「后来才明白：问，是人跟牲口隔的那一道。」"}}]}]},adv_g570_jizhang:{id:"adv_g570_jizhang",title:"路遇驼背阿婆——在青羊观替人情记着账",mother:"M8",channel:"T1",rarity:1,entry:{node:"lj_qingyang",chance:.07},stages:[{xinglu:"是岁青羊观逢驼背阿婆。驼背阿婆的话糙，理却直——「账要当众记、背后清——记账人自己先不能藏私。」",text:"驼背阿婆正给一户人家抄账——抄完把原册还人家，抄本自己留：「一式两份，两头作数。」「我这账，记的不是钱。」驼背阿婆敲敲一面写满还账记号的墙，「你欠谁一顿饭、谁替你垫过棺材本、你小时候谁背你趟过河——这些，钱还不清，礼还不上，就记在我这儿。记着，人情就还活着。」「考考你。」驼背阿婆合上账本，「两个人，一个欠一个还，你先记谁？——想想再答，这一笔记下去，就是规矩。」",options:[{label:"「我誊这页。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」驼背阿婆笑了，「张家的牛吃了李家的苗，是闲事；王家的娃读了书没人束脩，是闲事；你小时候发高热，邻家婶子背你走过三条街——也是闲事。这世上的情分，全是『闲事』堆出来的。我记的就是这些——你说的正事，反倒用不着我记。」"}}]},{xinglu:"是岁青羊观一课。驼背阿婆把话说到根上——「我这账本不是讨债的——是替人把「该记得」留住。」",text:"「记账人也有难处。」驼背阿婆说，「最难的一回，差一点把这柜账烧了。」「断二十年的死结，靠的不是我。」驼背阿婆说，「是账。两家为了一头牲口的账翻了脸，各说各的理，说到后来连当初谁欠谁都吵不清了。我翻出二十年前的老册子——记着呢：两家当年合伙买牛，牛钱各半，牛死了一家多用了两年。白纸黑字，两家老人都画了押。」驼背阿婆把册子往桌上一放，「两家人看着自己爹娘的押，当场就哭了。第二天合伙把坟头的草都拔了。你说账是什么？账是死人替活人留的话——我不过是替死人开口。」驼背阿婆合上账本：「客人，账理就一句话——欠的记着，还的记着，两头都不忘，人情就断不了。你带走这一句，我这柜子就没白守。」",options:[{label:"「它开着门，我就放心。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"义",text:"在驼背阿婆账上被记了一笔：「今天有个客人，听完了整本账」"},text_after:"「当得起什么。」驼背阿婆连连摆手，「我这行，说到底是替人管着念想。念想是他们的，我只是个保管员。」可你看得出来，他说这话时腰板挺得笔直——一个一辈子被几千户人信着的人，那份挺直，是拿三十年的笔一笔一笔撑起来的。"}},{label:"「账本又不是靠山。」",end:!0,effect:{stat:{wuxing:1},text_after:"「靠山？」驼背阿婆把账本举起来，「靠山会倒，靠人会跑，靠钱会花完——靠账呢？账是死的，可它记得的事是活的。你走投无路那天，敲开一户人家的门，报上名姓，人家翻出账本：『你家当年救济过我们……』——你说这不是靠山，什么才是？我这柜子，是几千户人的老底。」"}}]}]},adv_g571_shouwu:{id:"adv_g571_shouwu",title:"在关墙戍楼，守着一件旧物的妇人",mother:"M5",channel:"T2",rarity:2,entry:{node:"tw_guanqiang",chance:.08},stages:[{xinglu:"是岁关墙戍楼逢妇人。妇人的话糙，理却直——「守着它，它就不是破烂；撒手了，它就是一堆废料。」",text:"妇人见了你，头一句就是：「别嫌它旧。」说的是一排旧船坞。「它在这儿站了几十年，看过的路人数都数不清。」妇人拍拍一排旧船坞，「东西不嫌人多——就嫌人忘。你多看它两眼，它就不算白站。」妇人忽然问你：「你说，我百年之后，这东西归谁？」问完自己先笑了：「急什么，还早。可这话总得问问人。」",options:[{label:"坐下陪妇人说说话",goto:1,effect:void 0},{label:"不搭话，绕着走",end:!0,effect:{stat:{wuxing:1},text_after:"「换是要换的，」妇人在你背后说，「可换下来旧的，总得有人管。都等着别人管，旧的就都成了垃圾。」你没回头，可这句话跟了你一路。"}}]},{xinglu:"是岁关墙戍楼一课。妇人把话说到根上——「我陪它一辈子，它记我一辈子，两清。」",text:"「有年发大水，」妇人望着一排旧船坞，「别人都撤了，我守着它没走。」「我算过账。」妇人扳着指头，「守它这些年，花的钱、挨的骂、误的工——全是赔的。可谁家孩子路过这儿喊一声『这东西还在啊』——这一声，全赚回来了。」妇人站起身，最后擦了一遍一排旧船坞：「天不早了。守物人的话就这么多——你要记，就记一句：物在人守。人要是都不守了，物就真没了。」",options:[{label:"「这条规矩，我带走。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"义",text:"在关墙戍楼听妇人讲守一排旧船坞的道理，助守一日"},text_after:"你帮着擦完了。手上的灰蹭了一袖子，心里却出奇地熨帖。妇人看着擦亮的一排旧船坞，半天说了句：「行了，今天这一遍，值。」你走出很远才咂摸出味儿来——他谢的不是你，是它今天又被人认真对待了一回。"}},{label:"「天下旧物多了，管不过来。」",end:!0,effect:{stat:{wuxing:1},text_after:"妇人也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g572_chuanyi:{id:"adv_g572_chuanyi",title:"马市的一课：老汉把手艺往下传",mother:"M3",channel:"T3",rarity:2,entry:{node:"tw_mashi",chance:.09},stages:[{xinglu:"是岁马市逢老汉。老汉的话糙，理却直——「我师父传我时说：教的是手，留的是心。」",text:"老汉正用一副传了三代的药戥示范，做坏了，当着徒弟的面拆了重来：「错不藏——藏了错，就传了错。」「我教徒弟，头一年不让碰一副传了三代的药戥。」老汉笑，「先看、先磨性子。心浮的人拿家伙什，糟蹋东西，也糟蹋自己。」老汉让徒弟先歇了，转过身来：「客人识字吧？帮我看看这册子上的字有没有错的——手艺传得走样，多半是从错字开始的。」",options:[{label:"「我试试。」",goto:1,effect:void 0},{label:"「手艺而已，不值一提。」",end:!0,effect:{stat:{wuxing:1},text_after:"「问挣钱？」老汉放下一副传了三代的药戥，「问这话的，十个里十个学不成。挣钱的手艺满街都是，可饿不死人的行当里，站得住的从来不是钱——是牌子。牌子怎么来的？活做人正。你要只为钱，趁早干别的，别糟蹋这行。」你脸上挂不住，可他说的你没法反驳。"}}]},{xinglu:"是岁马市一课。老汉把话说到根上——「我把一辈子拆成手艺，你拿去接着活。」",text:"老汉指指墙上挂的一幅旧字：「我师父写的。我挂了三十年，今天念给你听。」「教不会的那部分，是火候。」老汉说，「差半分，药性不对、木头开裂、线走歪——这半分我说了三十年，徒弟们还是得自己烧坏三锅料才能懂。所以我改了法子：先让他们烧坏——心疼了，耳朵就开了。」老汉把一副传了三代的药戥放回原位，郑重其事：「手艺人就说手艺人的话。你今天听的多，能带走一句就够——做什么都行，把手上的活当人看。」",options:[{label:"「谢先生一课。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"看老汉带徒一下午，学会「骂是疼」的道理"},text_after:"你上了手，做得歪歪扭扭。老汉在旁边看着，不催不笑，等你做完才说：「歪归歪，下手不虚——你是块料，就是没人给你上过头一课。」你问什么头一课。他说：「敢在自己人面前做坏。多少有天分的人，就毁在不敢露怯上。」这句话你记了很多年。"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」老汉不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g573_haiyuan:{id:"adv_g573_haiyuan",title:"在佛骨塔下院，替故人还愿的驼背阿婆",mother:"M4",channel:"T1",rarity:2,entry:{node:"tw_foguta",chance:.08},stages:[{xinglu:"是岁佛骨塔下院逢驼背阿婆。驼背阿婆的话糙，理却直——「一个愿就是一条路，替人走路的，自己也有路走。」",text:"佛骨塔下院里，驼背阿婆捧着一张画了一半的画出神——你一问，他说这是故人留下的。「他说过，这事办成了，他就了无遗憾。」驼背阿婆望着一张画了一半的画，「他走了两年，我走了两万里的路。你说值不值？我不算这个账——我只知道，他临终看我的那一眼，我一辈子忘不掉。」驼背阿婆忽然问你：「客人识路广——你听过一张画了一半的画的去处么？随便一点线索，我都谢。」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「路远事烦，别找了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「路远事烦？」驼背阿婆笑了，「路是死的，事是活的。你嫌烦的事，兴许正是别人临终攥着的念想。我不怪你——年轻时我也这么想。就当我今天这些话，是说给二十岁的我听的。」你脸上一热，他已转身走远。"}}]},{xinglu:"是岁佛骨塔下院一课。驼背阿婆把话说到根上——「我不怕愿多——我怕的是没人记得那些愿。」",text:"「我老婆子生前总念叨，」驼背阿婆声音软下来，「这个愿，是为她还的。」「蹊跷事是这样的：那年到地方，收信的人家早搬了。」驼背阿婆说，「我打听三个月，问遍十里八乡——就在我要走的前一天，一个后生找上门：我是他孙子，爷爷临终说，会有人送东西来。」驼背阿婆摊开手，「你说，愿认路，还是我认路？我不知道。我只知道，愿不能停在半道。」驼背阿婆重新收拾好行囊：「客人的话我记下了。愿还得接着赶路——它等不起，我也不能老。」他冲你拱手，「你若哪天也遇上该还的愿——别拖。拖，是还愿这行唯一的死敌。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"恩",text:"为驼背阿婆的故人之愿指了路，了却半桩心愿"},text_after:"你把记得的线索全说了——竟真有一条有用。驼背阿婆愣在原地，半晌，深深作了个揖：「客人，你今天替一个走了两年的人，把愿往前推了三里地。」他非要留给你一样谢礼，你说不必，他坚持：「愿上的账，不能欠。你收下——不然我这一路，就白背了心债。」"}},{label:"「快些走吧，别误了我赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「帮不上不打紧。」驼背阿婆摆摆手，「别缠着我——这话就伤人了。我讨的不是你的帮，是你让一步路。让一步路，天塌不下来。」他让到道旁，先请你走。你从他身边过的时候，忽然觉得这一步，让得自己心里发虚。"}}]}]},adv_g574_zengxing:{id:"adv_g574_zengxing",title:"路遇清瘦老者——在关外荒驿白送路上的东西",mother:"M1",channel:"T2",rarity:1,entry:{node:"tw_huangyi",chance:.11},stages:[{xinglu:"是岁关外荒驿逢清瘦老者。清瘦老者的话糙，理却直——「赠人一程，自己脚下的路也宽了一寸。」",text:"关外荒驿人人都认得清瘦老者和他那一桶拴在渡口的姜汤——你初来乍到，也被他拦下了。「起头也有人笑我傻。」清瘦老者靠着一桶拴在渡口的姜汤坐下，「白摆着，让人白拿。我说你看着——一个月后你再笑。一个月后，笑我的人绕路也来喝一口。」清瘦老者忽然问你：「你往后还走这条路么？」不等答，他自己笑了：「走不走都一样。东西在这儿，路就在这儿。」",options:[{label:"「我取一份，谢谢。」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白给的好事？」清瘦老者哈哈大笑，「你算算这笔账：我一年搭进去几贯钱，换来这条道上的人夜里敢走、白天敢歇——你说值几贯？好事从来都白给，只是给的人不说。」你把他的话琢磨了一路，到家门口才咂摸出味儿来。"}}]},{xinglu:"是岁关外荒驿一课。清瘦老者把话说到根上——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"「有一年冬天，来了个贼。」清瘦老者说起这事，倒像说旁人。「得意的是那边——」清瘦老者指的远处有户人家，「那家两口子，当年落难，在我这儿白吃了半个月。后来缓过来了，在自家村口也摆了一摊。再后来，那条道上每隔十里就有一摊——不是我摆的。我这一缸茶，泡出了一条道的人心。你说值不值？」清瘦老者朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"义",text:"在关外荒驿受清瘦老者一程之赠，学「路上有人惦记」的道理"},text_after:"「路上的人认路上的人。」你把这话嚼了一路。后来你在他乡的渡口，看见一个陌生人冒着雨给等船的人撑伞——没人认识谁，可人人都往伞下凑。你站在雨里看着，忽然懂了：那条道上的规矩，早就走出关外荒驿了。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」清瘦老者居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一桶拴在渡口的姜汤像一方小小的印，盖在漫长的路上。"}}]}]},adv_g575_shouye:{id:"adv_g575_shouye",title:"赌坊来了个夜里替人醒着的清瘦老者",mother:"M2",channel:"T3",rarity:2,entry:{node:"hq_dufang",chance:.1},stages:[{xinglu:"是岁赌坊逢清瘦老者。清瘦老者的话糙，理却直——「夜里的规矩比白天大——因为夜里没人看着，全凭自觉。」",text:"夜里你到赌坊，清瘦老者提着一棚待产的牲口巡到跟前，先给你照了个亮。「夜里我谁也不查。」清瘦老者说，「我就是走。走给睡的人听——听见脚步，贼不敢动，病人心安，失眠的知道天总会亮。我这一双脚，是赌坊的定心丸。」「夜深了。」清瘦老者看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「夜里的事，讲讲。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「出息？」清瘦老者笑了，「我这行没出息——没出息到二十年没人抢。可你想想，谁夜里敢不睡？不是我不想睡，是赌坊几百户人拿觉换了我的不睡。」他敲了敲一棚待产的牲口，「出息这东西，白天论的。夜里的账，另算。」你将信将疑地走了。后来你在异乡的夜里病倒，是个守夜的老人照看了你——那一刻你想起这句话，眼睛忽然就热了。"}}]},{xinglu:"是岁赌坊一课。清瘦老者把话说到根上——「白天人挤人，夜里心贴心——夜里肯应你一声的，都是家里人。」",text:"「守夜二十年，我就遇过一回真险。」清瘦老者说到这儿，摸了摸一棚待产的牲口。「师父那句话是：守夜守的不是夜，是人心里那点亮。」清瘦老者摩挲着一棚待产的牲口，「我用了二十年才懂——灯灭了可以再点，人心里的灯灭了，夜里就真黑了。所以我巡夜从不偷懒：我的脚步声，就是几百户人心里那盏灯的灯芯响。」「天快亮了。」清瘦老者打了个梆，「五更，天下太平。你听——鸡都叫了。这就是守夜人的一天：什么都没发生，就是最大的事。」",options:[{label:"「这一夜，谢过了。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"恩",text:"为清瘦老者递了一句生面孔的话，替赌坊夜里防了一手"},text_after:"你带走了那一半话。夜里赶路时你学着清瘦老者的样子，给后来的人照个亮。有回一个后生问你是谁，你说：「一个守夜的教我的——夜里的另一半，留给夜里的人。」后生似懂非懂。可他往后也给人照亮了——清瘦老者的灯，就这么传到了你手上。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」清瘦老者指指自己的眼睛，「我这双眼二十年没睡过一个整觉——赌坊每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g576_shiyi:{id:"adv_g576_shiyi",title:"黑市的一课：白发老丈替失物寻主人",mother:"M6",channel:"T1",rarity:3,entry:{node:"hq_heishi",chance:.08},stages:[{xinglu:"是岁黑市逢白发老丈。白发老丈的话糙，理却直——「失物认人——你替它找到主人，它比你还高兴。」",text:"白发老丈见你打量一筐孩子丢在路边的玩物，主动开了口：「别看它们破——件件都有来处，件件都在等人。」「丢东西分两种。」白发老丈说，「丢东西的和丢人的。丢东西的来我这儿找——丢人的，我自己去找。去年我从人牙子手里领回来一个走失的娃，就是从一件小袄上认出来的。」白发老丈忽然问你：「客人一路走来，可曾在别处见过这样的物件？」他把一件失物举到你眼前。",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「失物还想着领？痴人。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不会找？」白发老丈叹口气，「客人，会找的人，丢的都是值钱东西。不会找的——老人丢了，孩子丢了，痴了的人丢了。他们自己找不了，家里人找疯了。我这行拾的，一半是物，一半是人。」他说完不再看你。你走出去几步，觉得方才那句话，轻佻得不像自己的。"}}]},{xinglu:"是岁黑市一课。白发老丈把话说到根上——「世上的失物比失物的人多——总得有人替它们排队等主人。」",text:"「我这里头，最贵的一件东西，」白发老丈指指一筐孩子丢在路边的玩物，「一文钱不值。可它等主人等了十五年。」「发懵的事是这样的：有个妇人丢了亡夫的一枚章，在我这儿登了记，急得三天没吃。」白发老丈说，「两年后东西寻着了，送上门——她看着章，忽然平静得很，说了声『原来在这』，就收下了，连谢都没谢。」白发老丈苦笑，「我懵了半个月。后来懂了：她这两年，是把人一点一点放下了。章送到了，她哀也尽了。我这一行，有时候送到的是东西，有时候送到的——是结局。」白发老丈把册子递给你看：「客人，失物账一页一页都在这儿。你帮不上不要紧——记住：往后你丢了东西，先想想它在谁手里；捡了东西，先想想它归谁。这两句话做到了，我这行就算白教了你。」",options:[{label:"「这行当，敬您一声。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"听白发老丈讲半只风筝的旧事，识得失物的轻重"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。白发老丈眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「你这是痴人行当。」",end:!0,effect:{stat:{wuxing:1},text_after:"「吃什么？」白发老丈指指墙角的一张木床、一只小灶，「我就住这儿。失物招领不收钱——我另有营生，替各家修修补补，饿不死。」他嘿嘿一笑，「你问的不是这个吧？你是问我图什么。图什么——图我娘。我娘丢了她的陪嫁镯子，急疯了。有人替她寻回来了。那年我十岁，站在门口看那个人把镯子递给我娘——我娘笑了。我这辈子，就想当那个人。」"}}]}]},adv_g577_wenlu:{id:"adv_g577_wenlu",title:"药人坊里只问不答的清瘦老者",mother:"M7",channel:"T2",rarity:1,entry:{node:"hq_yaorenfang",chance:.12},stages:[{xinglu:"是岁药人坊逢清瘦老者。清瘦老者的话糙，理却直——「答是别人的，问才是自己的——会问的人，走哪儿都带着老师。」",text:"药人坊里，清瘦老者守着一张折了又折的路引，面前立着块牌子：「只问不答」。「我这一张折了又折的路引上挂满了问句。」清瘦老者指给你看，「有客人替我答的，有我自己想了三十年的。挂在这儿——路过的人看一眼，想一会儿，这一会儿，就值。」「你替我想想。」清瘦老者把一张写着问句的纸条递过来，「这个问题挂了三年没人答。你说说看——答不好也不要紧。」",options:[{label:"「这个利息，我还。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」清瘦老者哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁药人坊一课。清瘦老者把话说到根上——「问题挂在这儿，不急着答——有些问题本身就是灯。」",text:"「我这儿来过三种人。」清瘦老者掰着指头，「你猜是哪三种？」「问题伤人那件事，我认。」清瘦老者说，「有年一个败了家的商人来问我，我脱口问了一句：你的家业里，哪一样是你自己的？他当场就崩了——后来我才听说，他败家就是因为这辈子全在替他爹活。我那一问，是把他最后一块遮羞布扯了。」清瘦老者沉默半晌，「可第二年他回来谢我。他说那一问疼是疼，疼完才知道疼的原来是假的。问题这东西——下刀的时候狠，愈合的时候快。可我打那以后，问之前，都先看看人扛不扛得住。」「我送你出门。」清瘦老者边走边说，「记住——路上遇事，先别急着找答案。先问自己一句：这事我是在看，还是在觉得？这一句，顶你半生的学费。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"恩",text:"在药人坊答了清瘦老者一问，得了他一句「认真想的人自带先生」"},text_after:"「先生就是你自己的心。」你出门时回头看了一眼——清瘦老者已经转回一张折了又折的路引前，又在写新问题了。你忽然明白这老头为什么从不给答案：答案是他给不起的——人人的路不一样。他给的是火折子，路得你自己摸黑走。可有了火折子，摸黑也走得直。"}},{label:"「答案拿来，问题免了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」清瘦老者把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g578_jizhang:{id:"adv_g578_jizhang",title:"路遇独臂客——在镇外乱葬岭替人情记着账",mother:"M8",channel:"T3",rarity:2,entry:{node:"hq_luanzangling",chance:.11},stages:[{xinglu:"是岁镇外乱葬岭逢独臂客。独臂客的话糙，理却直——「账要当众记、背后清——记账人自己先不能藏私。」",text:"独臂客见你生面孔，先递茶再开口：「客人路过的吧？有没有账，都坐坐——我这儿不只是记账的。」「有人问我，死人欠的账记来做什么。」独臂客说，「记。儿子长大来翻账——看见他爹当年受过谁的恩、还过谁的债，他就知道自己是个什么根底。账本就是家谱，还是最老实的那一页。」「你识字吧？」独臂客把笔递过来，「帮我誊一页。誊账有个讲究——字要端正，心要放平。你试试。」",options:[{label:"「报个名姓，帮我翻翻。」",goto:1,effect:void 0},{label:"「你这行当，多管闲事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记它做什么？」独臂客把笔搁下，「你不记，它就不存在了么？不——它在你心里烂着，在他心里烂着，两败俱伤。记出来，才有得还、有得清、有得忘。账不是记仇——是把烂在心里的东西，拿到日头底下晾晾。」"}}]},{xinglu:"是岁镇外乱葬岭一课。独臂客把话说到根上——「一笔账两头记——欠的人记着还，还的人记着情，两头都记着，人就亲了。」",text:"「我这行也有对头。」独臂客冷笑一声，「有人最恨我这本账——你猜是谁？」「记错的那笔，是早年一个后生替他病重的爹来还账。」独臂客声音哑了，「我记成『还清』，其实差着半吊。他爹咽气前问起，还念叨着那半吊。等我发现，人已经没了，账差了，说不清了。」独臂客翻开账本给我看——那页边上有行小字：「错在我，补录于三年后，按利全还，还账人：他儿子。」——「他儿子在外头挣了三年，回来把半吊连本带利还了，还非要多还一份。我说不该多。他说：我爹没还完的账，我替他记得体面些。从那天起，我每笔记三遍。」「我这行干到死。」独臂客说，「死了我这账传给徒弟——徒弟再传徒弟。账本不怕旧，就怕断。你哪天路过，看看它还开着门不——开着，就说明有人接着记呢。」",options:[{label:"「这碗茶，敬记账人。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"恩",text:"听独臂客讲大饥年保账的旧事，识得一页纸的分量"},text_after:"你替他跑了一趟，把一册抄本送到了邻县。收账的是个白胡子老者，翻开一看就红了眼：「还有人记着这笔……」你回程时独臂客已在门口候着——他不要你讲细节，只问了一句：「送到就行了？」你说送到了。他长出一口气：「好。这一笔，两头都活了。」"}},{label:"「账本又不是靠山。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」独臂客笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g579_shouwu:{id:"adv_g579_shouwu",title:"在入坞山门，守着一件旧物的清瘦老者",mother:"M5",channel:"T1",rarity:1,entry:{node:"bc_yaomen",chance:.09},stages:[{xinglu:"是岁入坞山门逢清瘦老者。清瘦老者的话糙，理却直——「我不守物——我守的是「还有人记得」这四个字。」",text:"入坞山门有人守着一口枯而不涸的老井——清瘦老者，守的年头比你的岁数还长。「它不是我的，是大家的。」清瘦老者摆摆手，「我就是替大家看着。你今天看它一眼，你也算半个守的。」清瘦老者递过来一块抹布：「搭把手？擦一擦你就懂了——懂了的人，往后走到哪儿都见不得东西受委屈。」",options:[{label:"帮着擦一遍一口枯而不涸的老井",goto:1,effect:void 0},{label:"「这种闲事，与我何干。」",end:!0,effect:{stat:{wuxing:1},text_after:"「换是要换的，」清瘦老者在你背后说，「可换下来旧的，总得有人管。都等着别人管，旧的就都成了垃圾。」你没回头，可这句话跟了你一路。"}}]},{xinglu:"是岁入坞山门一课。清瘦老者把话说到根上——「守着它，它就不是破烂；撒手了，它就是一堆废料。」",text:"「守物人最怕什么，你知道么？」清瘦老者问你，没等你答，「最怕自己也觉得它没用了。」「我算过账。」清瘦老者扳着指头，「守它这些年，花的钱、挨的骂、误的工——全是赔的。可谁家孩子路过这儿喊一声『这东西还在啊』——这一声，全赚回来了。」清瘦老者朝一口枯而不涸的老井作了个揖，转身又朝你作了个揖：「一个替它，一个替它谢你。往后不管你走多远——记得这世上还有人在守着点什么东西，你心里就有底。」",options:[{label:"「往后路过，我来看它。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"受清瘦老者所托，允诺路过时看顾一口枯而不涸的老井"},text_after:"你帮着擦完了。手上的灰蹭了一袖子，心里却出奇地熨帖。清瘦老者看着擦亮的一口枯而不涸的老井，半天说了句：「行了，今天这一遍，值。」你走出很远才咂摸出味儿来——他谢的不是你，是它今天又被人认真对待了一回。"}},{label:"「这话太重，我不敢当。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」清瘦老者点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g580_chuanyi:{id:"adv_g580_chuanyi",title:"药市大街的一课：盲眼老者把手艺往下传",mother:"M3",channel:"T2",rarity:2,entry:{node:"bc_yaoshi",chance:.07},stages:[{xinglu:"是岁药市大街逢盲眼老者。盲眼老者的话糙，理却直——「徒弟学不学得会看天分，教不教得会看良心。」",text:"盲眼老者正用一套齐整的木工墨斗示范，做坏了，当着徒弟的面拆了重来：「错不藏——藏了错，就传了错。」「外行看手艺，看的是巧。」盲眼老者说，「内行看的是匀——匀了才稳，稳了才久。做人一个理。」「来，站我旁边看。」盲眼老者招招手，「看一遍，顶听十遍。」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"「这些老规矩，过时了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过时了？」盲眼老者不急不恼，「老规矩过不过时，不看年头，看它护不护人。你哪天吃了没规矩的亏，自然会想起今天这话。」你嘴上应着，心里不服。三年后你真吃了那亏——想起这话时，人在异乡，败得一塌糊涂。"}}]},{xinglu:"是岁药市大街一课。盲眼老者把话说到根上——「我师父传我时说：教的是手，留的是心。」",text:"盲眼老者指指墙上挂的一幅旧字：「我师父写的。我挂了三十年，今天念给你听。」「我为什么当着徒弟面拆了重做？」盲眼老者说，「因为躲一次错，徒弟就学会藏错；认一次错，徒弟就学会认错。手艺上的毛病小，人心上的毛病大——我宁可在活上丢脸，不在人上丢魂。」盲眼老者最后擦了一遍手，朝你拱手：「客人慢走。手艺人的话糙，理不糙——你今儿听的这些，够你在别的行当里用一辈子。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"在药市大街受盲眼老者一课，悟「敬艺」之理"},text_after:"「能传多久？」盲眼老者想了想，「看天。可我告诉你我的算法：只要还有人肯为一个细节较真——这门手艺就活着。你今天盯着我这活看了半晌，就在较真。所以今天，它又多活了一天。」"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要绝就绝。」盲眼老者淡淡地说，「手艺绝不绝，不看我这代人喊多响——看下代人肯不肯弯腰。我弯了三十年腰了，够了。绝了也不冤：它来的时候有人敬，走的时候有人送，全始全终。」你出门时回头看了一眼，盲眼老者已经又坐回一套齐整的木工墨斗前——绝不绝的话撂在那儿，手上的活一天没停。"}}]}]},adv_g581_haiyuan:{id:"adv_g581_haiyuan",title:"药王庙的一课：老妇替故人还愿",mother:"M4",channel:"T3",rarity:2,entry:{node:"bc_yaowangmiao",chance:.12},stages:[{xinglu:"是岁药王庙逢老妇。老妇的话糙，理却直——「故人最大的悲哀不是死——是心愿烂在没人知道的地方。」",text:"你见老妇对着一封没寄出去的信自言自语，像在跟什么人回话。「他说过，这事办成了，他就了无遗憾。」老妇望着一封没寄出去的信，「他走了两年，我走了两万里的路。你说值不值？我不算这个账——我只知道，他临终看我的那一眼，我一辈子忘不掉。」「客人赶路，可否捎我一段？」老妇诚恳道，「多个人说话，路就不显得长——我讲给你听，这愿是个什么愿。」",options:[{label:"「我听过，说与你听。」",goto:1,effect:void 0},{label:"「故人的东西，留着何用。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」老妇站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁药王庙一课。老妇把话说到根上——「人走了，愿不能跟着走——愿得有人替他走完。」",text:"「替人还愿二十年，我攒了一肚子故事。」老妇说，「讲一个你听着——听完你就懂我为什么还在走。」「那回邪门事，我不止遇到过一回——回回都在我想撒手的时候。」老妇说，「有一年我病倒在客栈，想着这愿怕是还不成了。第二天清早，隔壁房一个货郎来借火，一搭话——他正是我要找的那家的远亲。你说这是菩萨安排？我不信菩萨。可我信：你认真办一件事，全天下都会给你让路。」「我走了。」老妇背起行囊，「这愿还完，我就回家种地——把替人还愿的道理，讲给村口的娃娃们听。让他们知道：这世上有一种债，还的是心安。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"义",text:"为老妇的故人之愿指了路，了却半桩心愿"},text_after:"你捎了他一程。一路上他把愿的来历讲了个通透，讲完长出一口气：「背了两年，今天讲顺了——讲顺了，就快了。」到了岔路口他下车，冲你长揖：「送佛送到西，你今天送的不止是我。」"}},{label:"「愿是虚的，人死了就完了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」老妇笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g582_zengxing:{id:"adv_g582_zengxing",title:"清瘦老者在山谷药田白送路上的东西",mother:"M1",channel:"T1",rarity:2,entry:{node:"bc_yaotian",chance:.09},stages:[{xinglu:"是岁山谷药田逢清瘦老者。清瘦老者的话糙，理却直——「白给的东西要正大光明地白给——藏着掖着，善就变了味。」",text:"山谷药田的路边，清瘦老者摆着一串挂在树上的旧草鞋，来者不问，取者不问。「你仔细看我的木牌。」清瘦老者指给你，「写的是『自取』，不是『施与』。一字之差——拿的人心里就平了。善这个东西，得把人的脸面一起护住才算善。」清瘦老者把东西塞到你手里：「拿着。别谢——要谢，往后你也给别人备一份。」",options:[{label:"「往后还走。」",goto:1,effect:void 0},{label:"「白拿的东西，来路不正。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不占便宜是好品性。」清瘦老者点头，「可我这不叫便宜——叫过路钱。你今天不喝我这口，往后你发达了在别处摆摊，让人白喝——这账就平了。」他硬塞给你，「路上没有白拿，只有先拿后还。你先欠着，我说这话不臊——你将来还得起。」"}}]},{xinglu:"是岁山谷药田一课。清瘦老者把话说到根上——「赠出去的每一件，都是投给这世道的一票——投它个好字。」",text:"「我这一串挂在树上的旧草鞋，起头不是给人用的。」清瘦老者声音低了，「是我给自己备的。」「得意的是那边——」清瘦老者指的远处有户人家，「那家两口子，当年落难，在我这儿白吃了半个月。后来缓过来了，在自家村口也摆了一摊。再后来，那条道上每隔十里就有一摊——不是我摆的。我这一缸茶，泡出了一条道的人心。你说值不值？」「我老了，这摊子早晚交出去。」清瘦老者望着路，「交给谁？交给先坐下来的那个人。谁肯坐下来陪它过日子，它就是谁的。你哪天路过歇脚——兴许就是你。」",options:[{label:"「路上见，老丈。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"听清瘦老者讲一盏灯化一个贼的旧事"},text_after:"你收下了。那包东西在行囊里放了很久，一直没舍得吃——不是舍不得，是想起清瘦老者说的「路上有人惦记」，就觉得这世上怎么走都走不黑。后来你也学他，在自家门前挂了壶凉茶。挂上去那天你才懂：那不是茶，是把当年受的那份踏实，接着往下传。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」清瘦老者居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一串挂在树上的旧草鞋像一方小小的印，盖在漫长的路上。"}}]}]},adv_g583_shouye:{id:"adv_g583_shouye",title:"试毒巷来了个夜里替人醒着的老人",mother:"M2",channel:"T2",rarity:1,entry:{node:"bc_shidu",chance:.09},stages:[{xinglu:"是岁试毒巷逢老人。老人的话糙，理却直——「夜里的规矩比白天大——因为夜里没人看着，全凭自觉。」",text:"老人守在一座桥洞的火盆旁，火光把他的影子拉得很长，见你近前，先问了句：「夜里赶路，有事？」「守夜人最要紧的不是胆，是觉浅。」老人笑道，「风吹草动，我在三里外的被窝里都能竖起耳朵。这不是本事——这是把心搁在试毒巷搁了二十年，搁熟了。」「往前头去有段黑路。」老人把灯举高了些，「我送你过——反正我也要巡到那边。」",options:[{label:"「陪您走一段。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不用我管？」老人收了灯，「好，我不管。可我巡到你家墙根，听见里头摔东西——我照旧多站一刻。为什么？我婆娘也摔过。摔东西的人，多半是喊救命喊不出声的。」他把灯转回去，「你家的事我不管——你的命，我夜里路过总得看一眼。」你那一夜睡得极不安稳。"}}]},{xinglu:"是岁试毒巷一课。老人把话说到根上——「白天是人管人，夜里是心管心——守夜守的就是那颗不该动的心。」",text:"「守夜二十年，我就遇过一回真险。」老人说到这儿，摸了摸一座桥洞的火盆。「当官的那位，姓陈。」老人说，「那年他赶考，盘缠被偷了，蹲在一座桥洞的火盆边上哭。我陪他坐了一夜，把攒的几吊钱塞给他——我婆娘还跟我吵了一架。后来他中了，回来找我，要给我修房子。我说不用——你记住这一夜就行：往后你坐堂，遇上夜里犯的事，先问问人家为什么夜里走这条路。」老人说，「他真照做了。去年他断了一桩案子——贼是贼，可贼的娘病着。他判了贼，也治了他娘的病。你说我这几吊钱，值不值？」「我这班，还守得动十年。」老人活动着腿脚，「十年后谁接？我挑着呢。你若哪天走投无路——来找我。守夜人缺人手，也缺心里有夜的人。」",options:[{label:"「保我十年太平。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"义",text:"听老人讲砸门四十七扇的旧事，识得守夜人的分寸"},text_after:"你带走了那一半话。夜里赶路时你学着老人的样子，给后来的人照个亮。有回一个后生问你是谁，你说：「一个守夜的教我的——夜里的另一半，留给夜里的人。」后生似懂非懂。可他往后也给人照亮了——老人的灯，就这么传到了你手上。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「名堂？」老人把灯举起来，「你看这灯照多远——三步。可走夜路的人，缺的就是这三步。」他放下灯，「名堂是白天的事。我夜里不图名堂——图的是试毒巷的狗都不叫唤。狗都不叫，就是真太平。你要图名堂，白天去图；你要图太平，咱们才是一路的。」"}}]}]},adv_g584_shiyi:{id:"adv_g584_shiyi",title:"老汉在采药人客栈替失物寻主人",mother:"M6",channel:"T3",rarity:1,entry:{node:"bc_kezhan",chance:.06},stages:[{xinglu:"是岁采药人客栈逢老汉。老汉的话糙，理却直——「丢东西的人分两种：丢得起的一笑了之，丢不起的——那种你得跑断腿。」",text:"老汉收着一筐孩子丢在路边的玩物，逢人先问一句「你可认得……」——问了十年，问了满城的摇头。「有人笑我守着一堆破烂。」老汉不恼，「我说你不懂——破烂搁在你家是破烂，搁在我这儿，是有主的。只等它的主人哪天想起来。人这一辈子，谁没落下过点什么？」老汉递给你一件失物：「你摸摸。摸完了你说说，它的主人是个什么样的人？」",options:[{label:"「搭把手，算我一个。」",goto:1,effect:void 0},{label:"「一堆破烂，守着做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人？」老汉摇头，「你丢了东西就知道了——丢东西的人，个个都是痴人。我见过丢了亡妻一支簪子的铁塔似的汉子，在我这儿哭成泪人。你笑痴——那是你的福气。真到了痴那天，你盼着世上多几个痴人。」他把门为你拉开，「慢走。愿你一辈子用不上我这行。」"}}]},{xinglu:"是岁采药人客栈一课。老汉把话说到根上——「拾遗不图利——图的是物归原主那一声「啊」。」",text:"「拾遗这行，也有发懵的时候。」老汉说，「讲一件，你听听值不值。」「认走三回的那位，是个老先生。」老汉说，「第一回认走怀表，第二回认走烟斗，第三回又要认走一顶帽子——我留了个心眼，问他东西上有什么记号。他答不上来。」老汉叹口气，「不是贼——是痴了的老爷子。他的东西都在儿子那儿，他自个儿记不得，看见像我库里描述的就认。我没拆穿，陪他坐了一下午，听他讲他丢的每一件东西——哪一件背后都是他的老伴儿。后来他儿子来谢我，说老爷子那晚睡了两年来头一个整觉。」「天不早了。」老汉点起灯，「我这儿夜里也开门——丢东西的人，是不分时辰的。你慢走，路上小心别落了东西。落了也不要紧——这世上还有我这样的人。」",options:[{label:"「两句话，我记牢了。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"义",text:"一眼认出包袱上的字迹，省了老汉三个月的腿"},text_after:"你摸着那件失物说了自己的猜测——「丢它的人手上有茧，是做粗活出身，可这物件绣工极细，是替珍视的人做的。」老汉怔了半天，说：「二十年，头一回有人把它说活。」他把它单独搁到一个格子里，「照你这么说，它主人家里必还有一个等它的人。我再寻十年，也值得。」"}},{label:"「你这是痴人行当。」",end:!0,effect:{stat:{wuxing:1},text_after:"「吃什么？」老汉指指墙角的一张木床、一只小灶，「我就住这儿。失物招领不收钱——我另有营生，替各家修修补补，饿不死。」他嘿嘿一笑，「你问的不是这个吧？你是问我图什么。图什么——图我娘。我娘丢了她的陪嫁镯子，急疯了。有人替她寻回来了。那年我十岁，站在门口看那个人把镯子递给我娘——我娘笑了。我这辈子，就想当那个人。」"}}]}]},adv_g585_wenlu:{id:"adv_g585_wenlu",title:"路遇婆婆——在澳港码头只问不答",mother:"M7",channel:"T1",rarity:1,entry:{node:"cl_aogang",chance:.13},stages:[{xinglu:"是岁澳港码头逢婆婆。婆婆的话糙，理却直——「我不教人——我提问题，路让人自己走。」",text:"你被婆婆叫住：「别急着走。你说——人为什么要问路？」「有人说我故弄玄虚。」婆婆不恼，「玄虚是我给你答案；我给你的是问题——问题这东西，你拿回去自己酿，酿出来的才解渴。」「你替我想想。」婆婆把一张写着问句的纸条递过来，「这个问题挂了三年没人答。你说说看——答不好也不要紧。」",options:[{label:"「这问题，我试试。」",goto:1,effect:void 0},{label:"「怪人一个，不理也罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」婆婆哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁澳港码头一课。婆婆把话说到根上——「问不丢人——不懂装懂才丢人。」",text:"「我最得意的一个问题，」婆婆压低了声音，「救过一个人。」「骂我的那位，是个急性子的商人。」婆婆点头认了，「他问怎么发财，我不答，反问他：你发财是要给谁看？他气得跳脚，骂了半天走了。半年后他回来，红着脸给我作揖——说他那半年净想我这问题，生意反而稳了：不图人看的买卖，才做得长。」婆婆笑道，「你看，我挨一句骂，换他半条正路——这账，赚。」「我送你出门。」婆婆边走边说，「记住——路上遇事，先别急着找答案。先问自己一句：这事我是在看，还是在觉得？这一句，顶你半生的学费。」",options:[{label:"「利息我必还。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"在婆婆店里吵了一架，各自往前挪了半步"},text_after:"「看，还是觉得——这一句你带走了。」婆婆满意地送你出门。后来你在生意上、恩怨里、抉择前，无数次问自己这一句。它不能替你做对的事——可它让你少做了许多自以为对的事。你从此逢人便传这句话，传的时候都说是从一个怪老头那儿听来的。"}},{label:"「故弄玄虚，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」婆婆把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g586_jizhang:{id:"adv_g586_jizhang",title:"鱼市的一课：妇人替人情记着账",mother:"M8",channel:"T2",rarity:1,entry:{node:"cl_yushi",chance:.08},stages:[{xinglu:"是岁鱼市逢妇人。妇人的话糙，理却直——「账不怕欠——怕的是没人记。记着，就还有还的一天。」",text:"妇人见你生面孔，先递茶再开口：「客人路过的吧？有没有账，都坐坐——我这儿不只是记账的。」「我这柜里也有死账。」妇人翻开一册，「欠账的人没了，绝了户。这账我不销——我把它抄出来，年年清明在庙前念一遍。不为讨——为的是告诉街坊：这个人来过，欠过，也被人欠过。没了户，不能连名都没了。」妇人打量你一番：「客人面生——有没有旧账落在我这儿？有的话，报个名姓，我一翻便知。」",options:[{label:"「先记欠的。」",goto:1,effect:void 0},{label:"「我不欠谁的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过去？」妇人摇头，「过得去的才叫过去。过不去的，你不理它，它就长在心里长成疙瘩。我这柜子里的账，一半是让人过得去的——账面摆出来，多少年的疙瘩，一句话就解了。」"}}]},{xinglu:"是岁鱼市一课。妇人把话说到根上——「账要当众记、背后清——记账人自己先不能藏私。」",text:"「有一笔账，记错了。」妇人说这话时，手都在抖——那是最早以前的事了。「这页上没几个钱。」妇人指着那页字，「记的是：某年大疫，西街王家把最后一副药让给了东街李家，自己没熬过去。李家记下这笔，三代人来还——还不到王家坟上，就还到王家剩下的老闺女身上：出嫁陪的嫁妆、逢年送的米、老了以后请的郎中。」妇人合上册子，「一副药换三代人的情。你说我这一柜子账，值多少钱？」「我这行干到死。」妇人说，「死了我这账传给徒弟——徒弟再传徒弟。账本不怕旧，就怕断。你哪天路过，看看它还开着门不——开着，就说明有人接着记呢。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"在鱼市受妇人一句账理：欠的记着，还的记着"},text_after:"你替他跑了一趟，把一册抄本送到了邻县。收账的是个白胡子老者，翻开一看就红了眼：「还有人记着这笔……」你回程时妇人已在门口候着——他不要你讲细节，只问了一句：「送到就行了？」你说送到了。他长出一口气：「好。这一笔，两头都活了。」"}},{label:"「记账记成痴，何苦。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」妇人笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g587_shouwu:{id:"adv_g587_shouwu",title:"海神庙来了个守着一件旧物的少年",mother:"M5",channel:"T3",rarity:1,entry:{node:"cl_haishenmiao",chance:.08},stages:[{xinglu:"是岁海神庙逢少年。少年的话糙，理却直——「东西替人记事，人替东西撑腰。」",text:"海神庙有人守着一块无字碑——少年，守的年头比你的岁数还长。少年说守这东西有讲究：「每天来看一眼，缺了补，脏了擦。不为别的——它要是哪天塌了，方圆几十里的人，心里都得空一块。」少年直起腰看着你：「客人，你信不信——东西也挑人。它今天让你站住了脚，说明它认你。」",options:[{label:"「守了多久了？」",goto:1,effect:void 0},{label:"「破烂一个，守它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"你绕着走了。走出去老远，风里飘来一句话似的调子——少年在给一块无字碑哼曲儿。你忽然明白：人家守得高兴，根本不在乎你看不看。这么一想，你的脚步倒轻快了。"}}]},{xinglu:"是岁海神庙一课。少年把话说到根上——「守着它，它就不是破烂；撒手了，它就是一堆废料。」",text:"「最难的不是守，是没人懂。」少年笑笑，「懂的人不来，来的人不懂——守着守着就只剩你一个人了。」「我算过账。」少年扳着指头，「守它这些年，花的钱、挨的骂、误的工——全是赔的。可谁家孩子路过这儿喊一声『这东西还在啊』——这一声，全赚回来了。」「我把本子给你看看就懂了。」少年翻开守物账——密密麻麻全是名字，「这些人都来看过它。你今天也来过——这账，会一直记下去。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"与少年共守一块无字碑一夜，学会守物的规矩"},text_after:"你把来处和去处都念了。念完少年笑得眼睛眯成一条缝：「好了，你们认识了。往后你不管走多远，它都算你认识的东西——人这辈子，认识的东西多了，心里就宽。」"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」少年点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g588_chuanyi:{id:"adv_g588_chuanyi",title:"船坞里把手艺往下传的清瘦老者",mother:"M3",channel:"T1",rarity:2,entry:{node:"cl_chuanwu",chance:.12},stages:[{xinglu:"是岁船坞逢清瘦老者。清瘦老者的话糙，理却直——「手艺人的坟头不用碑——他的手艺活在别人手上，就是碑。」",text:"清瘦老者见了你，先把手上的活做完才抬头：「客人别笑话，手艺人的规矩，做不完的活不抬头。」清瘦老者说这行最金贵的不是手艺，是规矩：「什么料配什么工、什么活收什么价——规矩乱了，手艺就散了。」「你要是感兴趣，我讲细点。」清瘦老者说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"「我帮您对对字。」",goto:1,effect:void 0},{label:"「我有急事，不多聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不值一提？」清瘦老者也不争辩，只把刚做好的活递给你看——那一处细节，你盯了半天才看出来门道。「你再看一遍，」他说，「不值一提的东西，为什么你一提就提不出来？」你臊了，他哈哈大笑：「逗你的。手艺不值一提，提的是心——你有心，就能看见。」"}}]},{xinglu:"是岁船坞一课。清瘦老者把话说到根上——「徒弟出师那天骂你，是好事——他敢自己走了。」",text:"「我这一只磨秃了毫的旧笔差点断在一桩事上。」清瘦老者摩挲着它，「你听听——听完你就明白手艺人为什么较真。」「成器的那个，如今在外头独当一面；走了样的那三个，拿了手艺去糊弄人。」清瘦老者说，「我记牢的是骂我最狠的那个——他嫌我严，走了。前年他回来磕头，说在外头吃了不懂规矩的亏。我没怪他——他这一圈弯路，就是他没听完的课。」清瘦老者最后擦了一遍手，朝你拱手：「客人慢走。手艺人的话糙，理不糙——你今儿听的这些，够你在别的行当里用一辈子。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"义",text:"看清瘦老者带徒一下午，学会「骂是疼」的道理"},text_after:"你站了一下午，看清瘦老者带徒弟。收工时他问你看出什么没有。你说：「您骂人的话，跟夸人的话一样多。」他大笑：「对喽！手艺人捧徒弟，是害他；骂徒弟，是疼他。你往后再带人，记住这个理。」"}},{label:"「说了这么多，不就是要钱。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要绝就绝。」清瘦老者淡淡地说，「手艺绝不绝，不看我这代人喊多响——看下代人肯不肯弯腰。我弯了三十年腰了，够了。绝了也不冤：它来的时候有人敬，走的时候有人送，全始全终。」你出门时回头看了一眼，清瘦老者已经又坐回一只磨秃了毫的旧笔前——绝不绝的话撂在那儿，手上的活一天没停。"}}]}]},adv_g589_haiyuan:{id:"adv_g589_haiyuan",title:"番商货栈来了个替故人还愿的独臂客",mother:"M4",channel:"T2",rarity:1,entry:{node:"cl_huozhan",chance:.13},stages:[{xinglu:"是岁番商货栈逢独臂客。独臂客的话糙，理却直——「愿这个东西，许的时候轻飘飘，还的时候千斤重。」",text:"番商货栈里，独臂客捧着一张画了一半的画出神——你一问，他说这是故人留下的。「他说过，这事办成了，他就了无遗憾。」独臂客望着一张画了一半的画，「他走了两年，我走了两万里的路。你说值不值？我不算这个账——我只知道，他临终看我的那一眼，我一辈子忘不掉。」「客人赶路，可否捎我一段？」独臂客诚恳道，「多个人说话，路就不显得长——我讲给你听，这愿是个什么愿。」",options:[{label:"「这字我还认得。」",goto:1,effect:void 0},{label:"「与我无关，让让。」",end:!0,effect:{stat:{wuxing:1},text_after:"「与我无关？」独臂客也不恼，「是啊，天下事都与谁无关呢？他跟我无关的时候，我欠了他一辈子。你走吧——愿你一辈子都用不上替人还愿。用不上，是福气。」"}}]},{xinglu:"是岁番商货栈一课。独臂客把话说到根上——「我不怕愿多——我怕的是没人记得那些愿。」",text:"「我老婆子生前总念叨，」独臂客声音软下来，「这个愿，是为她还的。」「那回邪门事，我不止遇到过一回——回回都在我想撒手的时候。」独臂客说，「有一年我病倒在客栈，想着这愿怕是还不成了。第二天清早，隔壁房一个货郎来借火，一搭话——他正是我要找的那家的远亲。你说这是菩萨安排？我不信菩萨。可我信：你认真办一件事，全天下都会给你让路。」独臂客把一小撮路上的干粮分给你：「同行一程，就是有缘。这个你拿着——路上的人情，也是愿的一部分。我替故人结的善缘，多一个是一个。」",options:[{label:"「善缘我收下了。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"为独臂客的故人之愿指了路，了却半桩心愿"},text_after:"你帮着辨出了那页纸上的字——缺的那一角，是收信人的名字。独臂客盯着那个名字看了许久：「对上了。就差这个字，我在县里翻了三天的户籍。」他抬头时眼眶红了，「客人，你今天不是帮我看字——你是替他把最后一句话，送到了门口。」"}},{label:"「快些走吧，别误了我赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」独臂客笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g590_zengxing:{id:"adv_g590_zengxing",title:"灯塔崖里白送路上的东西的白发老丈",mother:"M1",channel:"T3",rarity:1,entry:{node:"cl_dengtaya",chance:.06},stages:[{xinglu:"是岁灯塔崖逢白发老丈。白发老丈的话糙，理却直——「赠人一程，自己脚下的路也宽了一寸。」",text:"灯塔崖人人都认得白发老丈和他那一盏风雨夜的引路灯——你初来乍到，也被他拦下了。「别多想，不是施舍。」白发老丈把东西推给你，「施舍是人上人下，我这个是递手——你渴了，我这里正好有。就这么简单。」白发老丈忽然问你：「你往后还走这条路么？」不等答，他自己笑了：「走不走都一样。东西在这儿，路就在这儿。」",options:[{label:"「您这摊子，摆了几年？」",goto:1,effect:void 0},{label:"「我不占人便宜。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」白发老丈愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁灯塔崖一课。白发老丈把话说到根上——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"「有一年冬天，来了个贼。」白发老丈说起这事，倒像说旁人。「最高兴的一回，是个哑巴。」白发老丈说，「他拿了我半年，一句话说不了。有天他忽然比划着——旁边的货郎给我翻：他说，他往后的营生有了，是帮渡口搬货，东家管饭。说完他给我磕了个头。」白发老丈抹了把脸，「我拦都没拦住。我不是图这个——可这个，比什么都沉。」「记住这条道的规矩。」白发老丈指指一盏风雨夜的引路灯，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"恩",text:"在灯塔崖白得一份干粮，后来也学着挂了一壶茶"},text_after:"「路上的人认路上的人。」你把这话嚼了一路。后来你在他乡的渡口，看见一个陌生人冒着雨给等船的人撑伞——没人认识谁，可人人都往伞下凑。你站在雨里看着，忽然懂了：那条道上的规矩，早就走出灯塔崖了。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」白发老丈居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一盏风雨夜的引路灯像一方小小的印，盖在漫长的路上。"}}]}]},adv_g591_shouye:{id:"adv_g591_shouye",title:"剑山道的一课：老人夜里替人醒着",mother:"M2",channel:"T1",rarity:1,entry:{node:"kw_jianshan",chance:.11},stages:[{xinglu:"是岁剑山道逢老人。老人的话糙，理却直——「白天人挤人，夜里心贴心——夜里肯应你一声的，都是家里人。」",text:"夜里你到剑山道，老人提着一队夜行的商旅巡到跟前，先给你照了个亮。「这条巡查路，我走了二十年，闭着眼都掉不进沟里。」老人拍拍路边的石头，「哪块石头松了我都知道——夜里出事，就出在这些白天没人看一眼的地方。」「往前头去有段黑路。」老人把灯举高了些，「我送你过——反正我也要巡到那边。」",options:[{label:"「有您这句保票，我睡了。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不用我管？」老人收了灯，「好，我不管。可我巡到你家墙根，听见里头摔东西——我照旧多站一刻。为什么？我婆娘也摔过。摔东西的人，多半是喊救命喊不出声的。」他把灯转回去，「你家的事我不管——你的命，我夜里路过总得看一眼。」你那一夜睡得极不安稳。"}}]},{xinglu:"是岁剑山道一课。老人把话说到根上——「夜里的规矩比白天大——因为夜里没人看着，全凭自觉。」",text:"「我师父传我一队夜行的商旅的时候说过一句话。」老人说，「我用了二十年才听懂。」「当官的那位，姓陈。」老人说，「那年他赶考，盘缠被偷了，蹲在一队夜行的商旅边上哭。我陪他坐了一夜，把攒的几吊钱塞给他——我婆娘还跟我吵了一架。后来他中了，回来找我，要给我修房子。我说不用——你记住这一夜就行：往后你坐堂，遇上夜里犯的事，先问问人家为什么夜里走这条路。」老人说，「他真照做了。去年他断了一桩案子——贼是贼，可贼的娘病着。他判了贼，也治了他娘的病。你说我这几吊钱，值不值？」「我这班，还守得动十年。」老人活动着腿脚，「十年后谁接？我挑着呢。你若哪天走投无路——来找我。守夜人缺人手，也缺心里有夜的人。」",options:[{label:"「这话我懂了。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"受老人一盏灯的照拂，往黑路上心里有了底"},text_after:"灯熄了，天亮了。你走出剑山道很远，回头看不见灯，可你知道它在——就像你知道这世上有一群人，一辈子活在别人的梦里，为的是别人的梦别变成噩梦。你朝着剑山道的方向作了个揖。天光大亮，路上人多了，谁也不知道你这一揖揖的是什么。"}},{label:"「你这灯，照不了多远。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」老人指指自己的眼睛，「我这双眼二十年没睡过一个整觉——剑山道每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g592_shiyi:{id:"adv_g592_shiyi",title:"老汉在剑炉街替失物寻主人",mother:"M6",channel:"T2",rarity:2,entry:{node:"kw_jianlu",chance:.08},stages:[{xinglu:"是岁剑炉街逢老汉。老汉的话糙，理却直——「东西无主的时候最可怜——可怜它们连个喊它名字的人都没有。」",text:"老汉在剑炉街整理一摞当铺里过期的死当，一件一件编号，比账房先生还仔细。「这一屋子，全是三年没人认的。」老汉拍了拍一摞当铺里过期的死当，「按理可以处置了。我不——三年找不到主人，我就再等三年。东西等得起，等不起的是万一哪天，那个找它的人来了，东西没了。」老汉忽然问你：「客人一路走来，可曾在别处见过这样的物件？」他把一件失物举到你眼前。",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「这行当，没出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人？」老汉摇头，「你丢了东西就知道了——丢东西的人，个个都是痴人。我见过丢了亡妻一支簪子的铁塔似的汉子，在我这儿哭成泪人。你笑痴——那是你的福气。真到了痴那天，你盼着世上多几个痴人。」他把门为你拉开，「慢走。愿你一辈子用不上我这行。」"}}]},{xinglu:"是岁剑炉街一课。老汉把话说到根上——「我守着一屋子没人要的东西，其实守着一屋子没人讲完的故事。」",text:"「我这里头，最贵的一件东西，」老汉指指一摞当铺里过期的死当，「一文钱不值。可它等主人等了十五年。」「发懵的事是这样的：有个妇人丢了亡夫的一枚章，在我这儿登了记，急得三天没吃。」老汉说，「两年后东西寻着了，送上门——她看着章，忽然平静得很，说了声『原来在这』，就收下了，连谢都没谢。」老汉苦笑，「我懵了半个月。后来懂了：她这两年，是把人一点一点放下了。章送到了，她哀也尽了。我这一行，有时候送到的是东西，有时候送到的——是结局。」「东西你拿走一件。」老汉忽然说，「不是送你——是托你。你走到别处，替它问问它的主人。我守在这儿出不去，你的腿比我的长。」",options:[{label:"「您守的不是破烂。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"受老汉所托，携一件失物出远门寻主"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。老汉眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「失物多了，你拾得过来？」",end:!0,effect:{stat:{wuxing:1},text_after:"「吃什么？」老汉指指墙角的一张木床、一只小灶，「我就住这儿。失物招领不收钱——我另有营生，替各家修修补补，饿不死。」他嘿嘿一笑，「你问的不是这个吧？你是问我图什么。图什么——图我娘。我娘丢了她的陪嫁镯子，急疯了。有人替她寻回来了。那年我十岁，站在门口看那个人把镯子递给我娘——我娘笑了。我这辈子，就想当那个人。」"}}]}]},adv_g593_wenlu:{id:"adv_g593_wenlu",title:"路遇清瘦老者——在矿石市只问不答",mother:"M7",channel:"T3",rarity:1,entry:{node:"kw_kuangshi",chance:.08},stages:[{xinglu:"是岁矿石市逢清瘦老者。清瘦老者的话糙，理却直——「天下没有蠢问题，只有不肯问的人。」",text:"清瘦老者坐在一盏陪他坐了半生的茶炉旁，见谁都想问两句——问得认真，听得也认真。「我这一盏陪他坐了半生的茶炉上挂满了问句。」清瘦老者指给你看，「有客人替我答的，有我自己想了三十年的。挂在这儿——路过的人看一眼，想一会儿，这一会儿，就值。」清瘦老者看着你：「客人，我问你——你这一路，是奔着什么来的？别急着答，想清楚再说。」",options:[{label:"「我是在奔着一条路。」",goto:1,effect:void 0},{label:"「怪人一个，不理也罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」清瘦老者哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁矿石市一课。清瘦老者把话说到根上——「人这一生，答案会过期——问题不会。」",text:"「我师父是个哑巴。」清瘦老者说这话时屋里静了静，「一辈子没说过一句话——可他教我的，全是问。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」清瘦老者缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」清瘦老者笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」「我这一盏陪他坐了半生的茶炉上的问题，谁都可以摘。」清瘦老者说，「摘走的记得回来还——还的不是纸条，是你自己酿的答案。利息不高，一辈子还一回就行。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"义",text:"在矿石市答了清瘦老者一问，得了他一句「认真想的人自带先生」"},text_after:"你摘走的问题是：「你怕的东西，值得你怕么？」这个问题你在心里盘了一年，最后自己写了个答案寄回去。半年后你路过矿石市，看见你的答案被挂上了墙，旁边还有七八张别人还的「利息」。你站在满墙的问句前——那一家小店，原来早成了半条街的心里话。"}},{label:"「故弄玄虚，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「从不问路？」清瘦老者看着你，忽然认真了，「客人，我不拦你。可我送你一句话：不问路的人，不是路盲——是路盲里胆子最大的。老天爷不在乎你问不问，它只管把你引到岔路口。你凭本事闯，闯对了是命大，闯错了——」他顿了顿，「没有人给你收尸。走吧。这话搁这儿，你哪天想起，算我的。」"}}]}]},adv_g594_jizhang:{id:"adv_g594_jizhang",title:"白发老丈在铸剑世家工坊替人情记着账",mother:"M8",channel:"T1",rarity:3,entry:{node:"kw_gongfang",chance:.07},stages:[{xinglu:"是岁铸剑世家工坊逢白发老丈。白发老丈的话糙，理却直——「账本比人活得长——我把账记清楚，情分就比人长寿。」",text:"白发老丈正给一户人家抄账——抄完把原册还人家，抄本自己留：「一式两份，两头作数。」「我这柜里也有死账。」白发老丈翻开一册，「欠账的人没了，绝了户。这账我不销——我把它抄出来，年年清明在庙前念一遍。不为讨——为的是告诉街坊：这个人来过，欠过，也被人欠过。没了户，不能连名都没了。」「考考你。」白发老丈合上账本，「两个人，一个欠一个还，你先记谁？——想想再答，这一笔记下去，就是规矩。」",options:[{label:"「我誊这页。」",goto:1,effect:void 0},{label:"「旧账就让它过去。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」白发老丈笑了，「张家的牛吃了李家的苗，是闲事；王家的娃读了书没人束脩，是闲事；你小时候发高热，邻家婶子背你走过三条街——也是闲事。这世上的情分，全是『闲事』堆出来的。我记的就是这些——你说的正事，反倒用不着我记。」"}}]},{xinglu:"是岁铸剑世家工坊一课。白发老丈把话说到根上——「我记的不是债——是这世上「有人还过」的证据。」",text:"「账本上最沉的一页，」白发老丈翻出来给你看，「不是钱最多的那页。你认认这页上的字。」「最恨我的是人贩子。」白发老丈冷冷道，「他们拐走的孩子，我账上都有底——哪家孩子哪年生、什么胎记、谁抱走的。他们烧过我的铺子，砍过我的门。可账在人心里的那份，他们烧不掉——街上人人替我记着。」白发老丈把柜子锁好，「我这账本为什么比官府的册子灵？因为官府的册子锁在库里，我的账——长在几千户人的嘴里。」「我这行干到死。」白发老丈说，「死了我这账传给徒弟——徒弟再传徒弟。账本不怕旧，就怕断。你哪天路过，看看它还开着门不——开着，就说明有人接着记呢。」",options:[{label:"「把我记上。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"帮白发老丈誊账一页，字正心平，得了保管员三分真传"},text_after:"你把那句话带走了。后来你受了人的恩，总会想起那笔「不欠谁的」的账——想起时脸就发热，热完了就认真去还。再后来你也学着记：谁帮过你、你欠过谁，一笔一笔记在心里。你还真把这些教给了你的孩子——账本没传下去，账理传下去了。"}},{label:"「死账就销了罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」白发老丈笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g595_shouwu:{id:"adv_g595_shouwu",title:"剑冢下院来了个守着一件旧物的盲眼老者",mother:"M5",channel:"T2",rarity:2,entry:{node:"kw_jianzhong",chance:.13},stages:[{xinglu:"是岁剑冢下院逢盲眼老者。盲眼老者的话糙，理却直——「我陪它一辈子，它记我一辈子，两清。」",text:"盲眼老者在剑冢下院守了一座路边义亭，见你打量，先开口说了它的来历。「有人问这破玩意儿有啥可守的。」盲眼老者笑了，「我说，你家里老人的旧物，你说有啥可留的？一个理——念想这东西，不作价。」盲眼老者忽然问你：「你说，我百年之后，这东西归谁？」问完自己先笑了：「急什么，还早。可这话总得问问人。」",options:[{label:"「它有故事，我愿听。」",goto:1,effect:void 0},{label:"「破烂一个，守它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"盲眼老者也没恼，只是摆摆手：「不守也对。守物这行，本来就挑人——不挑出个肯停脚的，守也守不住。」你走出去老远，回头一看，他还在擦。你忽然觉得，这世上的道理，一半在书里，一半在这样的人手里。"}}]},{xinglu:"是岁剑冢下院一课。盲眼老者把话说到根上——「守到后来，分不清是我守它，还是它守我。」",text:"「我师父守它三十年，我接了二十年。」盲眼老者说，「加起来五十年，还没它站着的年头长。」「动摇过的那回，是它塌了一角。」盲眼老者说，「我哭了半宿，第二天开始学着修。守物人都是这么过来的——先是舍不得，再是学不会，最后学会了。」「我把本子给你看看就懂了。」盲眼老者翻开守物账——密密麻麻全是名字，「这些人都来看过它。你今天也来过——这账，会一直记下去。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"义",text:"在剑冢下院听盲眼老者讲守一座路边义亭的道理，助守一日"},text_after:"你把来处和去处都念了。念完盲眼老者笑得眼睛眯成一条缝：「好了，你们认识了。往后你不管走多远，它都算你认识的东西——人这辈子，认识的东西多了，心里就宽。」"}},{label:"「天下旧物多了，管不过来。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」盲眼老者点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g596_chuanyi:{id:"adv_g596_chuanyi",title:"在岛链渔村，把手艺往下传的盲眼老者",mother:"M3",channel:"T3",rarity:2,entry:{node:"qd_yucun",chance:.11},stages:[{xinglu:"是岁岛链渔村逢盲眼老者。盲眼老者的话糙，理却直——「手上的功夫十年教得会，手上的分寸三十年说不清。」",text:"岛链渔村的作坊里传出说话声：盲眼老者在讲一只装满竹篾的旧筐的用法，讲一句，停半晌，让徒弟自己悟。「外行看手艺，看的是巧。」盲眼老者说，「内行看的是匀——匀了才稳，稳了才久。做人一个理。」「来，站我旁边看。」盲眼老者招招手，「看一遍，顶听十遍。」",options:[{label:"「为什么是这个形？」",goto:1,effect:void 0},{label:"不感兴趣，转身走",end:!0,effect:{stat:{wuxing:1},text_after:"「过时了？」盲眼老者不急不恼，「老规矩过不过时，不看年头，看它护不护人。你哪天吃了没规矩的亏，自然会想起今天这话。」你嘴上应着，心里不服。三年后你真吃了那亏——想起这话时，人在异乡，败得一塌糊涂。"}}]},{xinglu:"是岁岛链渔村一课。盲眼老者把话说到根上——「徒弟学不学得会看天分，教不教得会看良心。」",text:"「我师父当年教我，可比现在狠多了。」盲眼老者笑着摇头。「师父那幅字写的是：手稳不如心稳。」盲眼老者望着墙，「我年轻时觉得这话虚。有一年赶工，我心里乱，手没抖，活却全歪了——那一刻我才懂：手是心的影子。从那天起，我教徒弟先教静心。」盲眼老者最后擦了一遍手，朝你拱手：「客人慢走。手艺人的话糙，理不糙——你今儿听的这些，够你在别的行当里用一辈子。」",options:[{label:"「您的手艺，不会断。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"义",text:"在岛链渔村亲手学做盲眼老者的活，得「敢露怯」之教"},text_after:"「能传多久？」盲眼老者想了想，「看天。可我告诉你我的算法：只要还有人肯为一个细节较真——这门手艺就活着。你今天盯着我这活看了半晌，就在较真。所以今天，它又多活了一天。」"}},{label:"「手艺早晚要绝。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要钱？」盲眼老者愣了一下，随即大笑，「我今天一个字没收你钱，还搭了一下午的茶——你要是听成了要钱，那我这一下午白讲了，你的耳朵也白带了。走吧走吧——」他摆摆手，笑骂道，「亏你今天还看了我半天活。看活不看人，你差得远呢。」"}}]}]},adv_g597_haiyuan:{id:"adv_g597_haiyuan",title:"路遇白发老丈——在岛主议会替故人还愿",mother:"M4",channel:"T1",rarity:2,entry:{node:"qd_yihui",chance:.07},stages:[{xinglu:"是岁岛主议会逢白发老丈。白发老丈的话糙，理却直——「我一辈子还不完的愿，就是我这辈子最富的家底。」",text:"白发老丈在岛主议会等人，等了一个没有地址的人——他要送的是一张画了一半的画。「他说过，这事办成了，他就了无遗憾。」白发老丈望着一张画了一半的画，「他走了两年，我走了两万里的路。你说值不值？我不算这个账——我只知道，他临终看我的那一眼，我一辈子忘不掉。」白发老丈忽然问你：「客人识路广——你听过一张画了一半的画的去处么？随便一点线索，我都谢。」",options:[{label:"「您这愿，尽到心了。」",goto:1,effect:void 0},{label:"「故人的东西，留着何用。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」白发老丈站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁岛主议会一课。白发老丈把话说到根上——「愿这个东西，许的时候轻飘飘，还的时候千斤重。」",text:"「说起这个愿的来历，」白发老丈坐下身来，「得从头讲。」「蹊跷事是这样的：那年到地方，收信的人家早搬了。」白发老丈说，「我打听三个月，问遍十里八乡——就在我要走的前一天，一个后生找上门：我是他孙子，爷爷临终说，会有人送东西来。」白发老丈摊开手，「你说，愿认路，还是我认路？我不知道。我只知道，愿不能停在半道。」白发老丈把一小撮路上的干粮分给你：「同行一程，就是有缘。这个你拿着——路上的人情，也是愿的一部分。我替故人结的善缘，多一个是一个。」",options:[{label:"「愿您一路顺遂。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"捎白发老丈一程，听了一个还愿人的故事"},text_after:"你捎了他一程。一路上他把愿的来历讲了个通透，讲完长出一口气：「背了两年，今天讲顺了——讲顺了，就快了。」到了岔路口他下车，冲你长揖：「送佛送到西，你今天送的不止是我。」"}},{label:"「这故事听着累。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」白发老丈站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g598_zengxing:{id:"adv_g598_zengxing",title:"望仙崖里白送路上的东西的老汉",mother:"M1",channel:"T2",rarity:1,entry:{node:"qd_wangxianya",chance:.1},stages:[{xinglu:"是岁望仙崖逢老汉。老汉的话糙，理却直——「路上的东西谁都需要，路上的心谁都不肯先给——我先给。」",text:"你打望仙崖过，老汉招呼你：「歇歇脚？不要钱，也别推——推就见外了。」「我年轻时走远路，饿昏在道上，是个不认识的老丈给了我半块饼。」老汉说，「那半块饼我记了四十年。我这一筐垫路的碎石，就是还他那半块——还不上他本人，就还给他那样的路人。」「客人腿脚快，是赶远路的？」老汉问完不等答，已经把东西包好了，「远路更要带——不是干粮，是个念想。」",options:[{label:"「您这摊子，摆了几年？」",goto:1,effect:void 0},{label:"「我不占人便宜。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不占便宜是好品性。」老汉点头，「可我这不叫便宜——叫过路钱。你今天不喝我这口，往后你发达了在别处摆摊，让人白喝——这账就平了。」他硬塞给你，「路上没有白拿，只有先拿后还。你先欠着，我说这话不臊——你将来还得起。」"}}]},{xinglu:"是岁望仙崖一课。老汉把话说到根上——「我送的不是东西，是「有人管你」这句话。」",text:"「我最得意的不是这一筐垫路的碎石。」老汉朝远处一指，「是那边——你看见没有？」「起头真是给自己备的。」老汉坦白道，「那年我落魄，怕自己哪天走投无路，就先备着——备着备着，先被人用了。用的人跟我说谢，我脸上臊——原来我备下的东西，早有人比我更需要。从那天起，这就不是我的退路了，是路上的公物。」老汉朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「规矩我守住了。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"恩",text:"在望仙崖白得一份干粮，后来也学着挂了一壶茶"},text_after:"「路上的人认路上的人。」你把这话嚼了一路。后来你在他乡的渡口，看见一个陌生人冒着雨给等船的人撑伞——没人认识谁，可人人都往伞下凑。你站在雨里看着，忽然懂了：那条道上的规矩，早就走出望仙崖了。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「哄你？」老汉笑了，「我哄你做什么？我又不要你的钱、不要你的命。我哄你，你就信了天下还有点好事——这买卖我亏了还是赚了？」他把东西又塞回你怀里，「拿着。信不信由你——东西是真的，渴了是真的，就这么简单。」"}}]}]},adv_g599_shouye:{id:"adv_g599_shouye",title:"在沉没宫门，夜里替人醒着的老人",mother:"M2",channel:"T3",rarity:1,entry:{node:"lg_gongmen",chance:.1},stages:[{xinglu:"是岁沉没宫门逢老人。老人的话糙，理却直——「守夜这行，眼睛不能好使——太好使了，看见的事多，心里搁不下。」",text:"夜里你到沉没宫门，老人提着一座桥洞的火盆巡到跟前，先给你照了个亮。「夜里我谁也不查。」老人说，「我就是走。走给睡的人听——听见脚步，贼不敢动，病人心安，失眠的知道天总会亮。我这一双脚，是沉没宫门的定心丸。」「夜深了。」老人看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「遇上过，才知灯金贵。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「认得黑路是好事。」老人没拦你，「可你认得的是路——路认不认你，两说。去年有个自认得路的，掉进了拆了半截的桥坑里，躺了一夜——他不知道那坑，我知道。」他举灯照了照那个方向，「喏，就那儿。坑还在，天亮我得上报。」你没再犟，跟着他走了那条亮路。"}}]},{xinglu:"是岁沉没宫门一课。老人把话说到根上——「白天是人管人，夜里是心管心——守夜守的就是那颗不该动的心。」",text:"「你以为守夜就是防贼？」老人摇头，「夜里的事，十件有九件不是贼。」「师父那句话是：守夜守的不是夜，是人心里那点亮。」老人摩挲着一座桥洞的火盆，「我用了二十年才懂——灯灭了可以再点，人心里的灯灭了，夜里就真黑了。所以我巡夜从不偷懒：我的脚步声，就是几百户人心里那盏灯的灯芯响。」老人把灯吹熄了——天光已经泛白。「灯不用了。」他说，「灯是夜里的东西。你记住这盏灯照过你——就够了。」",options:[{label:"「您的班，值得。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"陪老人守了半宿一座桥洞的火盆，学会「夜里的另一半」"},text_after:"天亮了。你按老人教的走了那条新路——果然避开了塌方段。回头望，老人已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜沉没宫门的太平，全是这根梆子敲出来的。"}},{label:"「守夜能守出什么名堂。」",end:!0,effect:{stat:{wuxing:1},text_after:"「名堂？」老人把灯举起来，「你看这灯照多远——三步。可走夜路的人，缺的就是这三步。」他放下灯，「名堂是白天的事。我夜里不图名堂——图的是沉没宫门的狗都不叫唤。狗都不叫，就是真太平。你要图名堂，白天去图；你要图太平，咱们才是一路的。」"}}]}]},adv_g600_shiyi:{id:"adv_g600_shiyi",title:"在龙骨回廊，替失物寻主人的老汉",mother:"M6",channel:"T1",rarity:1,entry:{node:"lg_huilang",chance:.06},stages:[{xinglu:"是岁龙骨回廊逢老汉。老汉的话糙，理却直——「东西无主的时候最可怜——可怜它们连个喊它名字的人都没有。」",text:"老汉在龙骨回廊整理一叠无主的田契，一件一件编号，比账房先生还仔细。「我这行有个规矩：不卖。」老汉说，「有人出大价钱买一叠无主的田契里的好货，我不卖。卖了这行就脏了——往后人家丢了东西，第一反应不是来找我，是猜我。」「你说，」老汉忽然问，「东西找到主人重要，还是主人放下了重要？我想了十年，没想明白。」",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「谁丢了东西自己不会找。」",end:!0,effect:{stat:{wuxing:1},text_after:"「破烂？」老汉也不恼，随手拿起一件，「这顶帽子，里面绣着一个『安』字——是个当娘的给儿子缝的。儿子当兵走了，帽子落在渡口。你说这是破烂——那这位当娘的，这三年托人问了七个州府，问的是什么？」他把帽子轻轻放回去，「破烂是没名字的东西。这儿的东西，个个有名字，只是暂时没人喊。」你出门时回头看了一眼——满屋子的东西在灯影里静着，忽然都不像破烂了。"}}]},{xinglu:"是岁龙骨回廊一课。老汉把话说到根上——「每件遗物背后都站着一个着急的人——我急他所急。」",text:"「我这行有个祖师爷。」老汉笑了，「说出来你都不信——是个邮差。」「认走三回的那位，是个老先生。」老汉说，「第一回认走怀表，第二回认走烟斗，第三回又要认走一顶帽子——我留了个心眼，问他东西上有什么记号。他答不上来。」老汉叹口气，「不是贼——是痴了的老爷子。他的东西都在儿子那儿，他自个儿记不得，看见像我库里描述的就认。我没拆穿，陪他坐了一下午，听他讲他丢的每一件东西——哪一件背后都是他的老伴儿。后来他儿子来谢我，说老爷子那晚睡了两年来头一个整觉。」老汉把册子递给你看：「客人，失物账一页一页都在这儿。你帮不上不要紧——记住：往后你丢了东西，先想想它在谁手里；捡了东西，先想想它归谁。这两句话做到了，我这行就算白教了你。」",options:[{label:"「愿您满屋的东西早归主。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"受老汉所托，携一件失物出远门寻主"},text_after:"「找主人要紧。」老汉点头，「可你方才那个问法好——问的是主人放下了没有。这些年我只顾找，忘了问这个。有的失物，主人早放下了，是我攥着不放。」他笑了，「所以你看，问路的功劳不在答——在问。你今天这一问，我这行当又多了一条规矩。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「再买就是？」老汉笑了，「钱能买回来的，都不叫失物。叫失物的，钱买不回来——亡人的东西、旧人的信、娃他娘缝的鞋。这些丢了，买一百件新的，心里那个窟窿还是圆不上。你年纪轻，还没到懂的时候——哪天懂了，别哭，来我这儿坐坐。」"}}]}]},adv_g601_wenlu:{id:"adv_g601_wenlu",title:"鲛人遗族聚落的一课：独臂客只问不答",mother:"M7",channel:"T2",rarity:1,entry:{node:"lg_jiaoluo",chance:.08},stages:[{xinglu:"是岁鲛人遗族聚落逢独臂客。独臂客的话糙，理却直——「问不丢人——不懂装懂才丢人。」",text:"独臂客坐在一块画着地图的旧木板旁，见谁都想问两句——问得认真，听得也认真。「有人说我故弄玄虚。」独臂客不恼，「玄虚是我给你答案；我给你的是问题——问题这东西，你拿回去自己酿，酿出来的才解渴。」「客人走南闯北，见得多。」独臂客凑近了些，「帮我评评，这个问题，问得蠢不蠢？」",options:[{label:"「我想清楚再答。」",goto:1,effect:void 0},{label:"「卖关子，无聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」独臂客哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁鲛人遗族聚落一课。独臂客把话说到根上——「问句是钩子——鱼上不上钩不要紧，水被搅活了就行。」",text:"「我这儿来过三种人。」独臂客掰着指头，「你猜是哪三种？」「我师父哑，怎么教我问？」独臂客说，「他用手指比划，写在沙地上。他写的第一个问句是：你今天看见了什么？我答：什么都看见了。他摇头，写：不——你看见的是你觉得的。这句话我琢磨了半辈子。到今天，我每天还问自己这一句。」独臂客指指一块画着地图的旧木板，「这上头挂的头一个问题，就是他写的。」独臂客把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「利息我必还。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"在鲛人遗族聚落答了独臂客一问，得了他一句「认真想的人自带先生」"},text_after:"你摘走的问题是：「你怕的东西，值得你怕么？」这个问题你在心里盘了一年，最后自己写了个答案寄回去。半年后你路过鲛人遗族聚落，看见你的答案被挂上了墙，旁边还有七八张别人还的「利息」。你站在满墙的问句前——那一家小店，原来早成了半条街的心里话。"}},{label:"「问题再好，不顶饭吃。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」独臂客把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g602_jizhang:{id:"adv_g602_jizhang",title:"老汉在补给岛替人情记着账",mother:"M8",channel:"T3",rarity:2,entry:{node:"nh_bujidao",chance:.1},stages:[{xinglu:"是岁补给岛逢老汉。老汉的话糙，理却直——「死账不销——销了，欠的人和被欠的人，心里都空一块。」",text:"老汉正给一户人家抄账——抄完把原册还人家，抄本自己留：「一式两份，两头作数。」「记账三十年，我笔底下没错过一文。」老汉说，「不是我算术好——是我每笔记两遍、念一遍、过三天再核一遍。账这东西，错一笔，一街的信就塌了。」老汉递给你一盏茶：「先别急着走。听我说说这账本上的头一页——听完你就知道，账不是冰的。」",options:[{label:"「这笔账，我也想记。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过去？」老汉摇头，「过得去的才叫过去。过不去的，你不理它，它就长在心里长成疙瘩。我这柜子里的账，一半是让人过得去的——账面摆出来，多少年的疙瘩，一句话就解了。」"}}]},{xinglu:"是岁补给岛一课。老汉把话说到根上——「记仇的不算记账人——记仇的账越记越窄，我这种账越记越宽。」",text:"「记账人也有难处。」老汉说，「最难的一回，差一点把这柜账烧了。」「师父考我的是：背错一笔账给我听。」老汉说，「我背了，背得一丝不差。他摇头说：你背的是字。他要的是我记错一笔——然后自己心疼。他说，不心疼账的记账人，记的是死数；心疼账的，记的才是人情。」老汉摩挲着账本，「我后来真记错过一回——心疼得半宿睡不着。从那晚起，我才算入了行。」老汉合上账本：「客人，账理就一句话——欠的记着，还的记着，两头都不忘，人情就断不了。你带走这一句，我这柜子就没白守。」",options:[{label:"「它开着门，我就放心。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"听老汉讲大饥年保账的旧事，识得一页纸的分量"},text_after:"你把那句话带走了。后来你受了人的恩，总会想起那笔「不欠谁的」的账——想起时脸就发热，热完了就认真去还。再后来你也学着记：谁帮过你、你欠过谁，一笔一笔记在心里。你还真把这些教给了你的孩子——账本没传下去，账理传下去了。"}},{label:"「死账就销了罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「靠山？」老汉把账本举起来，「靠山会倒，靠人会跑，靠钱会花完——靠账呢？账是死的，可它记得的事是活的。你走投无路那天，敲开一户人家的门，报上名姓，人家翻出账本：『你家当年救济过我们……』——你说这不是靠山，什么才是？我这柜子，是几千户人的老底。」"}}]}]},adv_g603_shouwu:{id:"adv_g603_shouwu",title:"清瘦老者在海市守着一件旧物",mother:"M5",channel:"T1",rarity:1,entry:{node:"nh_haishi",chance:.13},stages:[{xinglu:"是岁海市逢清瘦老者。清瘦老者的话糙，理却直——「守到后来，分不清是我守它，还是它守我。」",text:"清瘦老者在海市守了半座旧石桥，见你打量，先开口说了它的来历。「这东西看着孤，其实不孤。」清瘦老者指给你看，「它身上有几十年的手印。守它的人一代传一代，手印摞手印——它比谁的家底都厚。」「帮我看看它哪儿不对。」清瘦老者退开半步，「外人一眼看出来的毛病，守的人反而看不见。」",options:[{label:"「您守它，图什么？」",goto:1,effect:void 0},{label:"不搭话，绕着走",end:!0,effect:{stat:{wuxing:1},text_after:"清瘦老者也没恼，只是摆摆手：「不守也对。守物这行，本来就挑人——不挑出个肯停脚的，守也守不住。」你走出去老远，回头一看，他还在擦。你忽然觉得，这世上的道理，一半在书里，一半在这样的人手里。"}}]},{xinglu:"是岁海市一课。清瘦老者把话说到根上——「东西旧了不怕，怕的是没人认它。」",text:"「守物人最怕什么，你知道么？」清瘦老者问你，没等你答，「最怕自己也觉得它没用了。」「我算过账。」清瘦老者扳着指头，「守它这些年，花的钱、挨的骂、误的工——全是赔的。可谁家孩子路过这儿喊一声『这东西还在啊』——这一声，全赚回来了。」「往后你路过，来看它一眼。」清瘦老者说，「不用你守——看一眼，它就多活一天。这买卖便宜吧？」",options:[{label:"「往后路过，我来看它。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"帮清瘦老者修缮半座旧石桥，海市的旧物得以长存"},text_after:"清瘦老者把红绳塞进你手里：「拿着。不是定礼——是念想。往后你在别处见着没人管的东西，手痒了，就想起这截绳。」后来你还真遇着过——一处塌了半边的旧亭子，你出钱请人修了。修完你自己都笑：这算什么，守物人的瘾。"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"清瘦老者也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g604_chuanyi:{id:"adv_g604_chuanyi",title:"婆婆在妖市把手艺往下传",mother:"M3",channel:"T2",rarity:1,entry:{node:"dh_yaoshi",chance:.08},stages:[{xinglu:"是岁妖市逢婆婆。婆婆的话糙，理却直——「我师父传我时说：教的是手，留的是心。」",text:"妖市的作坊里传出说话声：婆婆在讲一只装满竹篾的旧筐的用法，讲一句，停半晌，让徒弟自己悟。「我收徒不收钱。」婆婆摆摆手，「收钱的手艺传不远——徒弟心里算账，手上就留不住分寸。我挑徒弟只看一样：肯不肯下笨功夫。」婆婆问你：「我这手艺，在外行人眼里是个什么分量？说实话，我不恼。」",options:[{label:"「为什么是这个形？」",goto:1,effect:void 0},{label:"「手艺而已，不值一提。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不值一提？」婆婆也不争辩，只把刚做好的活递给你看——那一处细节，你盯了半天才看出来门道。「你再看一遍，」他说，「不值一提的东西，为什么你一提就提不出来？」你臊了，他哈哈大笑：「逗你的。手艺不值一提，提的是心——你有心，就能看见。」"}}]},{xinglu:"是岁妖市一课。婆婆把话说到根上——「最好的传法不是教——是让他看你做了三十年。」",text:"婆婆说起一个走了的徒弟，说到一半停了：「不提了。可你听我讲完——这事跟我这手艺有关。」「成器的那个，如今在外头独当一面；走了样的那三个，拿了手艺去糊弄人。」婆婆说，「我记牢的是骂我最狠的那个——他嫌我严，走了。前年他回来磕头，说在外头吃了不懂规矩的亏。我没怪他——他这一圈弯路，就是他没听完的课。」「你要是也有一门营生，」婆婆说，「记得往远处传。不一定要收徒——你把活做正了，看着的人自然学。」",options:[{label:"「谢先生一课。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"恩",text:"受婆婆所赠一句行话，行走江湖多了一面镜子"},text_after:"你站了一下午，看婆婆带徒弟。收工时他问你看出什么没有。你说：「您骂人的话，跟夸人的话一样多。」他大笑：「对喽！手艺人捧徒弟，是害他；骂徒弟，是疼他。你往后再带人，记住这个理。」"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要钱？」婆婆愣了一下，随即大笑，「我今天一个字没收你钱，还搭了一下午的茶——你要是听成了要钱，那我这一下午白讲了，你的耳朵也白带了。走吧走吧——」他摆摆手，笑骂道，「亏你今天还看了我半天活。看活不看人，你差得远呢。」"}}]}]},adv_g605_haiyuan:{id:"adv_g605_haiyuan",title:"在万妖山，替故人还愿的妇人",mother:"M4",channel:"T3",rarity:1,entry:{node:"dh_wanyao",chance:.08},stages:[{xinglu:"是岁万妖山逢妇人。妇人的话糙，理却直——「人走了，愿不能跟着走——愿得有人替他走完。」",text:"你见妇人对着一句没说出口的道歉自言自语，像在跟什么人回话。「家里人劝我，人走了就放下。」妇人摇头，「放下是给活人的宽心话。可愿不是包袱——愿是路标。我把这个愿还了，往后他坟头的草，我看着都顺眼。」妇人忽然问你：「客人识路广——你听过一句没说出口的道歉的去处么？随便一点线索，我都谢。」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"「人都没了，何必呢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」妇人站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁万妖山一课。妇人把话说到根上——「我一辈子还不完的愿，就是我这辈子最富的家底。」",text:"「说起这个愿的来历，」妇人坐下身来，「得从头讲。」「那回邪门事，我不止遇到过一回——回回都在我想撒手的时候。」妇人说，「有一年我病倒在客栈，想着这愿怕是还不成了。第二天清早，隔壁房一个货郎来借火，一搭话——他正是我要找的那家的远亲。你说这是菩萨安排？我不信菩萨。可我信：你认真办一件事，全天下都会给你让路。」「我走了。」妇人背起行囊，「这愿还完，我就回家种地——把替人还愿的道理，讲给村口的娃娃们听。让他们知道：这世上有一种债，还的是心安。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"受妇人所托记下善缘，替走了的人结一个活缘"},text_after:"你捎了他一程。一路上他把愿的来历讲了个通透，讲完长出一口气：「背了两年，今天讲顺了——讲顺了，就快了。」到了岔路口他下车，冲你长揖：「送佛送到西，你今天送的不止是我。」"}},{label:"「我帮不上，别缠着我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」妇人站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g606_zengxing:{id:"adv_g606_zengxing",title:"在化形妖城，白送路上的东西的老人",mother:"M1",channel:"T1",rarity:1,entry:{node:"dh_huaxing",chance:.09},stages:[{xinglu:"是岁化形妖城逢老人。老人的话糙，理却直——「我送的不是东西，是「有人管你」这句话。」",text:"化形妖城的路边，老人摆着一包缝在树洞里的针线，来者不问，取者不问。「我年轻时走远路，饿昏在道上，是个不认识的老丈给了我半块饼。」老人说，「那半块饼我记了四十年。我这一包缝在树洞里的针线，就是还他那半块——还不上他本人，就还给他那样的路人。」老人把东西塞到你手里：「拿着。别谢——要谢，往后你也给别人备一份。」",options:[{label:"「这道理我认。」",goto:1,effect:void 0},{label:"「我不占人便宜。」",end:!0,effect:{stat:{wuxing:1},text_after:"「来路？」老人也不恼，把本子推给你看——进货的、出账的，一笔一笔清清楚楚。「我自己掏的钱，自己种的地。白给，是我乐意，不是我有诈。」他把东西又往前推了推，「你防备人是对的——路上是多坏人。可你把好人也一并防了，亏的是你自己。」你迟疑着收了，那东西用着，到底比别的甜些。"}}]},{xinglu:"是岁化形妖城一课。老人把话说到根上——「善不留名不是清高——是留了名，来的人就不好意思拿了。」",text:"「赠了这些年，也有糟心事。」老人说，「讲一件，你别学我现在的脸色。」「起头真是给自己备的。」老人坦白道，「那年我落魄，怕自己哪天走投无路，就先备着——备着备着，先被人用了。用的人跟我说谢，我脸上臊——原来我备下的东西，早有人比我更需要。从那天起，这就不是我的退路了，是路上的公物。」「记住这条道的规矩。」老人指指一包缝在树洞里的针线，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「路上见，老丈。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"在化形妖城受老人一程之赠，学「路上有人惦记」的道理"},text_after:"「我可没说一定是我。」你摆手。老人笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一包缝在树洞里的针线边——像路长出来的一部分。"}},{label:"「别拿这些哄我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」老人居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一包缝在树洞里的针线像一方小小的印，盖在漫长的路上。"}}]}]},adv_g607_shouye:{id:"adv_g607_shouye",title:"佛国香市里夜里替人醒着的老汉",mother:"M2",channel:"T2",rarity:2,entry:{node:"xm_xiangshi",chance:.08},stages:[{xinglu:"是岁佛国香市逢老汉。老汉的话糙，理却直——「一夜平安，就是守夜人最大的功劳——可没人知道这一夜。」",text:"老汉守着一园将熟的瓜果，见你夜行，老远就招呼：「来的？前头黑，跟着我走一段。」「夜里赶路的，十个里有三个心里揣着事。」老汉给你照着亮，「我不问你什么事——我就把你送到亮处。人到了亮处，事就小了一半。」「夜里的事，你遇上过么？」老汉问你，「遇上过就知道我这盏灯的用处了。」",options:[{label:"「陪您走一段。」",goto:1,effect:void 0},{label:"「黑路我自己认得。」",end:!0,effect:{stat:{wuxing:1},text_after:"「出息？」老汉笑了，「我这行没出息——没出息到二十年没人抢。可你想想，谁夜里敢不睡？不是我不想睡，是佛国香市几百户人拿觉换了我的不睡。」他敲了敲一园将熟的瓜果，「出息这东西，白天论的。夜里的账，另算。」你将信将疑地走了。后来你在异乡的夜里病倒，是个守夜的老人照看了你——那一刻你想起这句话，眼睛忽然就热了。"}}]},{xinglu:"是岁佛国香市一课。老汉把话说到根上——「白天人挤人，夜里心贴心——夜里肯应你一声的，都是家里人。」",text:"「守夜二十年，我就遇过一回真险。」老汉说到这儿，摸了摸一园将熟的瓜果。「师父那句话是：守夜守的不是夜，是人心里那点亮。」老汉摩挲着一园将熟的瓜果，「我用了二十年才懂——灯灭了可以再点，人心里的灯灭了，夜里就真黑了。所以我巡夜从不偷懒：我的脚步声，就是几百户人心里那盏灯的灯芯响。」「天快亮了。」老汉打了个梆，「五更，天下太平。你听——鸡都叫了。这就是守夜人的一天：什么都没发生，就是最大的事。」",options:[{label:"「天亮了，好走。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"为老汉递了一句生面孔的话，替佛国香市夜里防了一手"},text_after:"「心里有夜的人。」你把这句话带了很多年。后来你做了点小营生，雇伙计先看人睡觉——都笑你怪。你想起老汉，也不解释。守夜人的道理，本来就是说给夜里的人听的。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「名堂？」老汉把灯举起来，「你看这灯照多远——三步。可走夜路的人，缺的就是这三步。」他放下灯，「名堂是白天的事。我夜里不图名堂——图的是佛国香市的狗都不叫唤。狗都不叫，就是真太平。你要图名堂，白天去图；你要图太平，咱们才是一路的。」"}}]}]},adv_g608_shiyi:{id:"adv_g608_shiyi",title:"路遇老妇——在佛骨塔替失物寻主人",mother:"M6",channel:"T3",rarity:1,entry:{node:"xm_foguta",chance:.13},stages:[{xinglu:"是岁佛骨塔逢老妇。老妇的话糙，理却直——「东西丢了有人找，人丢了没人寻——我干的是寻人的活。」",text:"佛骨塔里，老妇守着一屋一船漂来的遗物，见你进来，先问一句：「客人丢过什么？」「你看这物件，针脚多细。」老妇捧着它给你看，「做它的人花的工夫，比它本身的价钱贵十倍。丢它的人找不找得着它，就差我这样的人肯不肯多问一句。」「你说，」老妇忽然问，「东西找到主人重要，还是主人放下了重要？我想了十年，没想明白。」",options:[{label:"「它像是个念旧的人丢的。」",goto:1,effect:void 0},{label:"「一堆破烂，守着做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「没出息。」老妇笑了，「对——没出息，饿不死，也发不了。可你告诉我，什么行当能让人二十年睡得着觉？我这行能。我每送回一件东西，就有一户人家少一夜的睡不着。」他拱拱手，「出息是活给别人看的，觉是自己睡的。慢走。」"}}]},{xinglu:"是岁佛骨塔一课。老妇把话说到根上——「拾起来的不只是东西——是有人落下的日子。」",text:"「我师父是官府的库吏出身。」老妇说，「他传我这行当，传的却不是收东西的法子。」「被忘了才是真的没了。」老妇说，「所以我这册子上的东西，一件都不许销。人忘了，我替他记着；他哪天想起来——哪怕想起来的是十年前的一件小事——东西还在，日子就还接得上。我这行当说到底，就是给人留个『接得上』。」老妇送你到门口，回身望着满屋一船漂来的遗物：「客人，你笑我守破烂也好，敬我守念想也好——这屋子东西，早晚会一件一件回到人手里。到那时候，我这屋子空了，我这心，也就满了。」",options:[{label:"「愿您满屋的东西早归主。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"一眼认出包袱上的字迹，省了老妇三个月的腿"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。老妇眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「再买就是？」老妇笑了，「钱能买回来的，都不叫失物。叫失物的，钱买不回来——亡人的东西、旧人的信、娃他娘缝的鞋。这些丢了，买一百件新的，心里那个窟窿还是圆不上。你年纪轻，还没到懂的时候——哪天懂了，别哭，来我这儿坐坐。」"}}]}]},adv_g609_wenlu:{id:"adv_g609_wenlu",title:"中年汉子在泉眼驿寺只问不答",mother:"M7",channel:"T1",rarity:3,entry:{node:"xm_yisi",chance:.07},stages:[{xinglu:"是岁泉眼驿寺逢中年汉子。中年汉子的话糙，理却直——「我不教人——我提问题，路让人自己走。」",text:"泉眼驿寺的人都认得中年汉子——那是个只提问题、从不给答案的怪人。「我这一只装满纸条的竹筒上挂满了问句。」中年汉子指给你看，「有客人替我答的，有我自己想了三十年的。挂在这儿——路过的人看一眼，想一会儿，这一会儿，就值。」「留个问题给你。」中年汉子说着要往你手里塞纸条，「不白留——哪天你想通了，回来告诉一声。这店里的规矩：问题不白送，得还利息。」",options:[{label:"「我是在奔着一条路。」",goto:1,effect:void 0},{label:"「你到底答不答。」",end:!0,effect:{stat:{wuxing:1},text_after:"「怪人就怪人。」中年汉子笑呵呵的，「泉眼驿寺人人都这么叫。可你也看见了——他们路过还是要看一眼我那牌子。为什么？怪话里头，偶尔藏着正经。人不能全信怪人，可也不能一个怪人都不信——全信了傻，全不信了苦。你自己掂量。」他冲你摆摆手，继续挂他的问题。"}}]},{xinglu:"是岁泉眼驿寺一课。中年汉子把话说到根上——「我问了一辈子——问出来的东西，比读出来的多。」",text:"「问了一辈子，也栽过跟头。」中年汉子说，「讲一件——讲完你就知道，问题也能伤人。」「三种人：一种问完就走，答案在他那不值钱；一种听完反驳我，跟我吵——这种人我欢喜，吵着吵着，两个人都往前挪了半步；还有一种，最难得——问完，回去想了十年，回来就为了跟我说一句『我想通了』。」中年汉子竖起一根手指，「一辈子遇上一个，我这店就白开不了——值。」「我送你出门。」中年汉子边走边说，「记住——路上遇事，先别急着找答案。先问自己一句：这事我是在看，还是在觉得？这一句，顶你半生的学费。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"在中年汉子店里吵了一架，各自往前挪了半步"},text_after:"你摘走的问题是：「你怕的东西，值得你怕么？」这个问题你在心里盘了一年，最后自己写了个答案寄回去。半年后你路过泉眼驿寺，看见你的答案被挂上了墙，旁边还有七八张别人还的「利息」。你站在满墙的问句前——那一家小店，原来早成了半条街的心里话。"}},{label:"「我从不问路，只看脚下的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不顶饭吃？」中年汉子不急不恼，「饭是吃的，问题是活的。光吃饭不想事的人，跟牲口拉磨一个样——磨转得再快，路一寸没走。我不是笑话你——我五十岁之前也是这么活的。」他拍拍一只装满纸条的竹筒，「后来才明白：问，是人跟牲口隔的那一道。」"}}]}]},adv_g610_jizhang:{id:"adv_g610_jizhang",title:"在十八峒总寨，替人情记着账的老妇",mother:"M8",channel:"T2",rarity:3,entry:{node:"nj_bazhai",chance:.05},stages:[{xinglu:"是岁十八峒总寨逢老妇。老妇的话糙，理却直——「我这账本不是讨债的——是替人把「该记得」留住。」",text:"你到十八峒总寨时，两个人正拉扯着找老妇评理——老妇翻开账本，一句话就断了案。「有人问我，死人欠的账记来做什么。」老妇说，「记。儿子长大来翻账——看见他爹当年受过谁的恩、还过谁的债，他就知道自己是个什么根底。账本就是家谱，还是最老实的那一页。」「你识字吧？」老妇把笔递过来，「帮我誊一页。誊账有个讲究——字要端正，心要放平。你试试。」",options:[{label:"「这笔账，我也想记。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「你不欠谁的——好啊。」老妇忽然笑得眼睛弯起来，「这话我就给你记上：某年某月某日，有位客人说，他不欠谁的。这一笔怎么用呢——你哪天受了人的恩，想起这笔账，就得掂量掂量：真不欠，还是不肯欠？不肯欠的人多，不欠的少。」他冲你举举茶碗，「客人，别恼。账记上了，就等你哪天来改。」"}}]},{xinglu:"是岁十八峒总寨一课。老妇把话说到根上——「记账人手上要清，心上要热——光清不热，是阎王；光热不清，是糊涂虫。」",text:"「你见过两家人为一笔账断了二十年的来往么？」老妇说，「我接手过。」「烧账的事，是大饥那年。」老妇说，「富户囤粮抬价，我这账上记着他们家欠下的十七户人情——都是灾年穷人帮过他们先人的。他们怕我这张账掀老底，半夜送来一箱金子，让我把那页烧了。」老妇冷冷道，「我把金子退了，账抄了三份：一份我收着，一份藏在庙里，一份连夜送到那十七户人手里。后来饥年过完，那富户的粮，被十七户人凭一页旧账联名告发了。官府问：谁记的账？——没人说。账在，就够了。」「替我记一笔。」老妇忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「它开着门，我就放心。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"义",text:"在十八峒总寨受老妇一句账理：欠的记着，还的记着"},text_after:"「当得起什么。」老妇连连摆手，「我这行，说到底是替人管着念想。念想是他们的，我只是个保管员。」可你看得出来，他说这话时腰板挺得笔直——一个一辈子被几千户人信着的人，那份挺直，是拿三十年的笔一笔一笔撑起来的。"}},{label:"「记账记成痴，何苦。」",end:!0,effect:{stat:{wuxing:1},text_after:"「靠山？」老妇把账本举起来，「靠山会倒，靠人会跑，靠钱会花完——靠账呢？账是死的，可它记得的事是活的。你走投无路那天，敲开一户人家的门，报上名姓，人家翻出账本：『你家当年救济过我们……』——你说这不是靠山，什么才是？我这柜子，是几千户人的老底。」"}}]}]},adv_g611_shouwu:{id:"adv_g611_shouwu",title:"瘴林来了个守着一件旧物的妇人",mother:"M5",channel:"T3",rarity:1,entry:{node:"nj_zhanglin",chance:.07},stages:[{xinglu:"是岁瘴林逢妇人。妇人的话糙，理却直——「它站了几百年，我陪它站几年，不算多。」",text:"妇人守着半座旧石桥，有人劝他卖掉换钱，他不肯，你也来得正好，听了满耳朵的道理。妇人给你看半座旧石桥上的旧痕：「每一道痕都有来历。守物人得认得它全部的伤——认得了，才轮得到你守。」妇人直起腰看着你：「客人，你信不信——东西也挑人。它今天让你站住了脚，说明它认你。」",options:[{label:"「守了多久了？」",goto:1,effect:void 0},{label:"「破烂一个，守它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"妇人没追出来。你走了几里地，越想越不对——人家守了几十年的东西，你一句「破烂」就打发了。回头补一句的时候，妇人正围着半座旧石桥忙，见了你也不提方才的事，只说：「回来了？搭把手。」你愣是没说出道歉的话——他已经把它翻篇了。"}}]},{xinglu:"是岁瘴林一课。妇人把话说到根上——「守物的规矩只有一条：别让它在你手里断。」",text:"「有人半夜来砸过它。」妇人说这话时语气很平，「我拦了。为这事儿挨了顿打——值得。」「我算过账。」妇人扳着指头，「守它这些年，花的钱、挨的骂、误的工——全是赔的。可谁家孩子路过这儿喊一声『这东西还在啊』——这一声，全赚回来了。」妇人朝半座旧石桥作了个揖，转身又朝你作了个揖：「一个替它，一个替它谢你。往后不管你走多远——记得这世上还有人在守着点什么东西，你心里就有底。」",options:[{label:"「这条规矩，我带走。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"与妇人共守半座旧石桥一夜，学会守物的规矩"},text_after:"妇人把红绳塞进你手里：「拿着。不是定礼——是念想。往后你在别处见着没人管的东西，手痒了，就想起这截绳。」后来你还真遇着过——一处塌了半边的旧亭子，你出钱请人修了。修完你自己都笑：这算什么，守物人的瘾。"}},{label:"「这话太重，我不敢当。」",end:!0,effect:{stat:{wuxing:1},text_after:"妇人也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g612_chuanyi:{id:"adv_g612_chuanyi",title:"路遇老汉——在雪原猎场把手艺往下传",mother:"M3",channel:"T1",rarity:1,entry:{node:"by_xueyuan",chance:.12},stages:[{xinglu:"是岁雪原猎场逢老汉。老汉的话糙，理却直——「传艺如点灯——你点了我，我点他，火就一直亮。」",text:"老汉见了你，先把手上的活做完才抬头：「客人别笑话，手艺人的规矩，做不完的活不抬头。」老汉教你认一只磨秃了毫的旧笔的门道：「你看这儿，磨了三十年才有的包浆。手艺也一样——急不来的东西，才立得住。」老汉让徒弟先歇了，转过身来：「客人识字吧？帮我看看这册子上的字有没有错的——手艺传得走样，多半是从错字开始的。」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"「手艺而已，不值一提。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过时了？」老汉不急不恼，「老规矩过不过时，不看年头，看它护不护人。你哪天吃了没规矩的亏，自然会想起今天这话。」你嘴上应着，心里不服。三年后你真吃了那亏——想起这话时，人在异乡，败得一塌糊涂。"}}]},{xinglu:"是岁雪原猎场一课。老汉把话说到根上——「徒弟出师那天骂你，是好事——他敢自己走了。」",text:"老汉指指墙上挂的一幅旧字：「我师父写的。我挂了三十年，今天念给你听。」「那个走了样的徒弟，拿这门手艺坑人。」老汉声音沉下来，「我上门去，当着人面把一只磨秃了毫的旧笔从他手里要走回来——手艺是从这上头学的，现在从这上头收回来。他哭，我也难受。可规矩就是规矩：艺不正，师收之。」老汉最后擦了一遍手，朝你拱手：「客人慢走。手艺人的话糙，理不糙——你今儿听的这些，够你在别的行当里用一辈子。」",options:[{label:"「您的手艺，不会断。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"受老汉所赠一句行话，行走江湖多了一面镜子"},text_after:"你站了一下午，看老汉带徒弟。收工时他问你看出什么没有。你说：「您骂人的话，跟夸人的话一样多。」他大笑：「对喽！手艺人捧徒弟，是害他；骂徒弟，是疼他。你往后再带人，记住这个理。」"}},{label:"「与我何干，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要钱？」老汉愣了一下，随即大笑，「我今天一个字没收你钱，还搭了一下午的茶——你要是听成了要钱，那我这一下午白讲了，你的耳朵也白带了。走吧走吧——」他摆摆手，笑骂道，「亏你今天还看了我半天活。看活不看人，你差得远呢。」"}}]}]},adv_g613_haiyuan:{id:"adv_g613_haiyuan",title:"剑冢里替故人还愿的婆婆",mother:"M4",channel:"T2",rarity:1,entry:{node:"by_jianzhong",chance:.09},stages:[{xinglu:"是岁剑冢逢婆婆。婆婆的话糙，理却直——「替死人办事，得比替活人办事更上心——死人不会催你，也不会谢你。」",text:"婆婆把一封没寄出去的信护在怀里避雨——护得比自己的性命还紧。「家里人劝我，人走了就放下。」婆婆摇头，「放下是给活人的宽心话。可愿不是包袱——愿是路标。我把这个愿还了，往后他坟头的草，我看着都顺眼。」「你给评评理。」婆婆把一封没寄出去的信递过来，「我这愿，还到这一步，算不算尽到心了？」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"「故人的东西，留着何用。」",end:!0,effect:{stat:{wuxing:1},text_after:"「与我无关？」婆婆也不恼，「是啊，天下事都与谁无关呢？他跟我无关的时候，我欠了他一辈子。你走吧——愿你一辈子都用不上替人还愿。用不上，是福气。」"}}]},{xinglu:"是岁剑冢一课。婆婆把话说到根上——「故人最大的悲哀不是死——是心愿烂在没人知道的地方。」",text:"「我老婆子生前总念叨，」婆婆声音软下来，「这个愿，是为她还的。」「早点还不上，是因为我放不下脸面。」婆婆认了，「当年跟他置气，他托的事我故意拖着。后来他走了，我提着一封没寄出去的信在他坟前跪了一夜——第二天启程。你还愿，一半还的是他的愿，一半还的是自己的脸。我这张老脸，路上磨掉了一半，如今才算个人。」「你要是记得今天这故事，」婆婆说，「往后见着满头白发的还愿人，别笑他痴。给他一碗水——他替这世上所有走了的人，捎着话呢。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"为婆婆的故人之愿指了路，了却半桩心愿"},text_after:"你帮着辨出了那页纸上的字——缺的那一角，是收信人的名字。婆婆盯着那个名字看了许久：「对上了。就差这个字，我在县里翻了三天的户籍。」他抬头时眼眶红了，「客人，你今天不是帮我看字——你是替他把最后一句话，送到了门口。」"}},{label:"「快些走吧，别误了我赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」婆婆笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g614_zengxing:{id:"adv_g614_zengxing",title:"少年在雪山剑院白送路上的东西",mother:"M1",channel:"T3",rarity:1,entry:{node:"by_jianyuan",chance:.13},stages:[{xinglu:"是岁雪山剑院逢少年。少年的话糙，理却直——「赠人一程，自己脚下的路也宽了一寸。」",text:"你路过雪山剑院，看见少年正把一盏风雨夜的引路灯摆放齐整——摆完冲空荡荡的路作了个揖。「起头也有人笑我傻。」少年靠着一盏风雨夜的引路灯坐下，「白摆着，让人白拿。我说你看着——一个月后你再笑。一个月后，笑我的人绕路也来喝一口。」「帮我记个账呗。」少年递过来一个小本子，「不是记谁拿了什么——是记今天又有几个人用了它。这账好看，你写一笔。」",options:[{label:"「这道理我认。」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「来路？」少年也不恼，把本子推给你看——进货的、出账的，一笔一笔清清楚楚。「我自己掏的钱，自己种的地。白给，是我乐意，不是我有诈。」他把东西又往前推了推，「你防备人是对的——路上是多坏人。可你把好人也一并防了，亏的是你自己。」你迟疑着收了，那东西用着，到底比别的甜些。"}}]},{xinglu:"是岁雪山剑院一课。少年把话说到根上——「路上的东西谁都需要，路上的心谁都不肯先给——我先给。」",text:"「我最得意的不是这一盏风雨夜的引路灯。」少年朝远处一指，「是那边——你看见没有？」「那年来了个贼，夜里偷我的东西不说，还砸了我的牌子。」少年说，「我第二天照样摆，牌子重写一块，添了四个字：『夜路慢行』。后来那贼又来——这回是白天，红着脸放下一捆柴，一句话没说走了。」少年呵呵地笑，「你瞧，善这东西不咬人，它泡人。泡久了，铁石心肠也软。」少年朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"恩",text:"在雪山剑院受少年一程之赠，学「路上有人惦记」的道理"},text_after:"「路上的人认路上的人。」你把这话嚼了一路。后来你在他乡的渡口，看见一个陌生人冒着雨给等船的人撑伞——没人认识谁，可人人都往伞下凑。你站在雨里看着，忽然懂了：那条道上的规矩，早就走出雪山剑院了。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」少年点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一盏风雨夜的引路灯，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]},adv_g615_shouye:{id:"adv_g615_shouye",title:"天阶遗址里夜里替人醒着的老汉",mother:"M2",channel:"T1",rarity:1,entry:{node:"kx_tianjie",chance:.07},stages:[{xinglu:"是岁天阶遗址逢老汉。老汉的话糙，理却直——「守一夜容易，守一年也不难——难的是守着守着，把别人的夜当成自己的夜。」",text:"老汉守着一盏渡口的夜航灯，见你夜行，老远就招呼：「来的？前头黑，跟着我走一段。」「这条巡查路，我走了二十年，闭着眼都掉不进沟里。」老汉拍拍路边的石头，「哪块石头松了我都知道——夜里出事，就出在这些白天没人看一眼的地方。」「你今晚睡得着么？」老汉忽然问你，「睡不着别硬躺——陪我走一段，守夜人最不缺的就是夜。」",options:[{label:"「有您这句保票，我睡了。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「出息？」老汉笑了，「我这行没出息——没出息到二十年没人抢。可你想想，谁夜里敢不睡？不是我不想睡，是天阶遗址几百户人拿觉换了我的不睡。」他敲了敲一盏渡口的夜航灯，「出息这东西，白天论的。夜里的账，另算。」你将信将疑地走了。后来你在异乡的夜里病倒，是个守夜的老人照看了你——那一刻你想起这句话，眼睛忽然就热了。"}}]},{xinglu:"是岁天阶遗址一课。老汉把话说到根上——「守夜人的觉，是睡给别人的——我少睡一觉，别人多睡一夜。」",text:"「你以为守夜就是防贼？」老汉摇头，「夜里的事，十件有九件不是贼。」「换班的事，是真出过。」老汉说，「有一年我病了半个月，换了个年轻的顶班。他守得也认真——可他睡觉沉。就那半个月，天阶遗址丢了两头牲口、走失了一个老人——老人后来在河滩上寻着的，冻的。」老汉声音哑了，「不是他坏——是这行当挑人。觉沉的人守夜，等于没人守。从那以后我收徒，头一件事：看他睡觉。」「你走吧，天亮了路好走。」老汉收了灯，「夜里的事你记着一半就行——另一半，是留给夜里的人的。」",options:[{label:"「您的班，值得。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"义",text:"陪老汉守了半宿一盏渡口的夜航灯，学会「夜里的另一半」"},text_after:"你带走了那一半话。夜里赶路时你学着老汉的样子，给后来的人照个亮。有回一个后生问你是谁，你说：「一个守夜的教我的——夜里的另一半，留给夜里的人。」后生似懂非懂。可他往后也给人照亮了——老汉的灯，就这么传到了你手上。"}},{label:"「守夜能守出什么名堂。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我照不了多远，是真的。」老汉看着手里的灯，居然认了，「可我熄了，还有下一盏——我挑的徒弟，正学着觉浅呢。灯照不了多远不要紧，要紧的是一直亮着。你要赶路就赶吧——」他让开道，「前头三里没灯。你走的时候，替我记着这三里的黑。哪天你点上什么，别忘了我这话。」"}}]}]},adv_g616_shiyi:{id:"adv_g616_shiyi",title:"玉虚宫残殿的一课：婆婆替失物寻主人",mother:"M6",channel:"T2",rarity:1,entry:{node:"kx_yuxu",chance:.11},stages:[{xinglu:"是岁玉虚宫残殿逢婆婆。婆婆的话糙，理却直——「东西丢了有人找，人丢了没人寻——我干的是寻人的活。」",text:"婆婆见你打量一船漂来的遗物，主动开了口：「别看它们破——件件都有来处，件件都在等人。」「我这行有个规矩：不卖。」婆婆说，「有人出大价钱买一船漂来的遗物里的好货，我不卖。卖了这行就脏了——往后人家丢了东西，第一反应不是来找我，是猜我。」婆婆递给你一件失物：「你摸摸。摸完了你说说，它的主人是个什么样的人？」",options:[{label:"「搭把手，算我一个。」",goto:1,effect:void 0},{label:"「失物还想着领？痴人。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不会找？」婆婆叹口气，「客人，会找的人，丢的都是值钱东西。不会找的——老人丢了，孩子丢了，痴了的人丢了。他们自己找不了，家里人找疯了。我这行拾的，一半是物，一半是人。」他说完不再看你。你走出去几步，觉得方才那句话，轻佻得不像自己的。"}}]},{xinglu:"是岁玉虚宫残殿一课。婆婆把话说到根上——「丢东西的人分两种：丢得起的一笑了之，丢不起的——那种你得跑断腿。」",text:"「我这里头，最贵的一件东西，」婆婆指指一船漂来的遗物，「一文钱不值。可它等主人等了十五年。」「师父传我的话是：物有主，主有心，心有急缓。」婆婆说，「收东西的法子三天就会，辨人心的功夫十年难成。丢了药方的人和丢了银子的，急法不一样；丢东西的穷人和丢东西的富人，找法也不一样。这行当的功夫，全在听人说丢东西那几句话里。」婆婆送你到门口，回身望着满屋一船漂来的遗物：「客人，你笑我守破烂也好，敬我守念想也好——这屋子东西，早晚会一件一件回到人手里。到那时候，我这屋子空了，我这心，也就满了。」",options:[{label:"「愿您满屋的东西早归主。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"恩",text:"在玉虚宫残殿帮婆婆归类失物，替七户人家拆了死结"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。婆婆眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「失物多了，你拾得过来？」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人就痴人。」婆婆坦然得很，「这世上总得有人痴——都精明着，丢的东西就真没了。你精明你的，我痴我的。哪天你精明不动了、累了，我这一屋子痴，兴许还能给你焐焐手。」"}}]}]},adv_g617_wenlu:{id:"adv_g617_wenlu",title:"路遇独臂客——在蜀山山门只问不答",mother:"M7",channel:"T3",rarity:1,entry:{node:"ss_shanmen",chance:.07},stages:[{xinglu:"是岁蜀山山门逢独臂客。独臂客的话糙，理却直——「天下没有蠢问题，只有不肯问的人。」",text:"你被独臂客叫住：「别急着走。你说——人为什么要问路？」「我这牌子写着『只问不答』，不是傲。」独臂客解释道，「是我发现——我一给答案，人就不想了。答案是个懒东西，问句才养人。」「我考考你。」独臂客眼睛一亮，「就一个问题——答上来，我这一块画着地图的旧木板上的问题随你挑一个带走。」",options:[{label:"「您考我。」",goto:1,effect:void 0},{label:"「你到底答不答。」",end:!0,effect:{stat:{wuxing:1},text_after:"「怪人就怪人。」独臂客笑呵呵的，「蜀山山门人人都这么叫。可你也看见了——他们路过还是要看一眼我那牌子。为什么？怪话里头，偶尔藏着正经。人不能全信怪人，可也不能一个怪人都不信——全信了傻，全不信了苦。你自己掂量。」他冲你摆摆手，继续挂他的问题。"}}]},{xinglu:"是岁蜀山山门一课。独臂客把话说到根上——「问不丢人——不懂装懂才丢人。」",text:"「我这儿来过三种人。」独臂客掰着指头，「你猜是哪三种？」「问题伤人那件事，我认。」独臂客说，「有年一个败了家的商人来问我，我脱口问了一句：你的家业里，哪一样是你自己的？他当场就崩了——后来我才听说，他败家就是因为这辈子全在替他爹活。我那一问，是把他最后一块遮羞布扯了。」独臂客沉默半晌，「可第二年他回来谢我。他说那一问疼是疼，疼完才知道疼的原来是假的。问题这东西——下刀的时候狠，愈合的时候快。可我打那以后，问之前，都先看看人扛不扛得住。」「我这一块画着地图的旧木板上的问题，谁都可以摘。」独臂客说，「摘走的记得回来还——还的不是纸条，是你自己酿的答案。利息不高，一辈子还一回就行。」",options:[{label:"「有您这样的店，是蜀山山门的福气。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"义",text:"在蜀山山门答了独臂客一问，得了他一句「认真想的人自带先生」"},text_after:"你收下那个问题，揣了三年。第三年秋天你在异乡的田埂上想通了——回去时独臂客的店还开着，你把答案丢进竹筒。后来听说他每逢初一就摇竹筒听响，笑着说：「这条又满了。」你不知道他说的哪条是你——可你知道，有个人的问题，替你养了三年的心。"}},{label:"「故弄玄虚，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」独臂客把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g618_jizhang:{id:"adv_g618_jizhang",title:"在剑阁，替人情记着账的白发老丈",mother:"M8",channel:"T1",rarity:1,entry:{node:"ss_jianzheng",chance:.08},stages:[{xinglu:"是岁剑阁逢白发老丈。白发老丈的话糙，理却直——「我这账本不是讨债的——是替人把「该记得」留住。」",text:"白发老丈见你生面孔，先递茶再开口：「客人路过的吧？有没有账，都坐坐——我这儿不只是记账的。」「我这账，记的不是钱。」白发老丈敲敲一面写满还账记号的墙，「你欠谁一顿饭、谁替你垫过棺材本、你小时候谁背你趟过河——这些，钱还不清，礼还不上，就记在我这儿。记着，人情就还活着。」「帮我断个案子。」白发老丈把两个争执的人拉到一处，「他们都信你外乡人嘴严。」",options:[{label:"「我来断。」",goto:1,effect:void 0},{label:"「我不欠谁的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「你不欠谁的——好啊。」白发老丈忽然笑得眼睛弯起来，「这话我就给你记上：某年某月某日，有位客人说，他不欠谁的。这一笔怎么用呢——你哪天受了人的恩，想起这笔账，就得掂量掂量：真不欠，还是不肯欠？不肯欠的人多，不欠的少。」他冲你举举茶碗，「客人，别恼。账记上了，就等你哪天来改。」"}}]},{xinglu:"是岁剑阁一课。白发老丈把话说到根上——「记账人手上要清，心上要热——光清不热，是阎王；光热不清，是糊涂虫。」",text:"「账本上最沉的一页，」白发老丈翻出来给你看，「不是钱最多的那页。你认认这页上的字。」「记错的那笔，是早年一个后生替他病重的爹来还账。」白发老丈声音哑了，「我记成『还清』，其实差着半吊。他爹咽气前问起，还念叨着那半吊。等我发现，人已经没了，账差了，说不清了。」白发老丈翻开账本给我看——那页边上有行小字：「错在我，补录于三年后，按利全还，还账人：他儿子。」——「他儿子在外头挣了三年，回来把半吊连本带利还了，还非要多还一份。我说不该多。他说：我爹没还完的账，我替他记得体面些。从那天起，我每笔记三遍。」白发老丈把茶续满：「别急着走。听账人的道理，不在账上——在你听完以后，回头看你自家那本账。人人心里都有一本，只是没人替你誊清。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"在剑阁受白发老丈一句账理：欠的记着，还的记着"},text_after:"你替他跑了一趟，把一册抄本送到了邻县。收账的是个白胡子老者，翻开一看就红了眼：「还有人记着这笔……」你回程时白发老丈已在门口候着——他不要你讲细节，只问了一句：「送到就行了？」你说送到了。他长出一口气：「好。这一笔，两头都活了。」"}},{label:"「账本又不是靠山。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」白发老丈笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g619_shouwu:{id:"adv_g619_shouwu",title:"蓬莱渡口里守着一件旧物的老人",mother:"M5",channel:"T2",rarity:1,entry:{node:"pl_dukou",chance:.07},stages:[{xinglu:"是岁蓬莱渡口逢老人。老人的话糙，理却直——「物不会说话，可物记得每一个守过它的人。」",text:"老人见了你，头一句就是：「别嫌它旧。」说的是一块无字碑。「它在这儿站了几十年，看过的路人数都数不清。」老人拍拍一块无字碑，「东西不嫌人多——就嫌人忘。你多看它两眼，它就不算白站。」老人直起腰看着你：「客人，你信不信——东西也挑人。它今天让你站住了脚，说明它认你。」",options:[{label:"「您守它，图什么？」",goto:1,effect:void 0},{label:"「东西旧了就该换。」",end:!0,effect:{stat:{wuxing:1},text_after:"老人没追出来。你走了几里地，越想越不对——人家守了几十年的东西，你一句「破烂」就打发了。回头补一句的时候，老人正围着一块无字碑忙，见了你也不提方才的事，只说：「回来了？搭把手。」你愣是没说出道歉的话——他已经把它翻篇了。"}}]},{xinglu:"是岁蓬莱渡口一课。老人把话说到根上——「东西没了可以再造，守的规矩断了就接不上。」",text:"老人收了抹布，话头一转：「守它这些年，也不是没动摇过。」「师父留的那句话，我琢磨了二十年。」老人说，「他写的是：守到你觉得是它在守你，才算入门。我当时不懂——现在懂了。它站在这儿，我就不敢倒下。」老人站起身，最后擦了一遍一块无字碑：「天不早了。守物人的话就这么多——你要记，就记一句：物在人守。人要是都不守了，物就真没了。」",options:[{label:"「这条规矩，我带走。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"在蓬莱渡口听老人讲守一块无字碑的道理，助守一日"},text_after:"你陪老人坐到日头偏西。临走他说：「今天这一坐，比擦十年灰有用。」你问为什么。他说：「东西怕的不是旧，是没人坐。有人肯坐，它就还是个去处。」"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"老人也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g620_chuanyi:{id:"adv_g620_chuanyi",title:"路遇盲眼老者——在仙市把手艺往下传",mother:"M3",channel:"T3",rarity:1,entry:{node:"pl_xianshi",chance:.13},stages:[{xinglu:"是岁仙市逢盲眼老者。盲眼老者的话糙，理却直——「最好的传法不是教——是让他看你做了三十年。」",text:"你一眼看见一把用了半辈子的凿子——那东西在盲眼老者手里，像长了骨头，每一寸都稳。盲眼老者教你认一把用了半辈子的凿子的门道：「你看这儿，磨了三十年才有的包浆。手艺也一样——急不来的东西，才立得住。」盲眼老者忽然把一把用了半辈子的凿子递过来：「来，上手试试？」",options:[{label:"「为什么是这个形？」",goto:1,effect:void 0},{label:"不感兴趣，转身走",end:!0,effect:{stat:{wuxing:1},text_after:"你没搭理就走了。盲眼老者也没留你，只在你背后继续教徒弟。可那句「错不藏」追了你半条街——你想起自己上回做错事推了个干净，脚步忽然就沉了。"}}]},{xinglu:"是岁仙市一课。盲眼老者把话说到根上——「传艺如点灯——你点了我，我点他，火就一直亮。」",text:"盲眼老者指指墙上挂的一幅旧字：「我师父写的。我挂了三十年，今天念给你听。」「成器的那个，如今在外头独当一面；走了样的那三个，拿了手艺去糊弄人。」盲眼老者说，「我记牢的是骂我最狠的那个——他嫌我严，走了。前年他回来磕头，说在外头吃了不懂规矩的亏。我没怪他——他这一圈弯路，就是他没听完的课。」「你要是也有一门营生，」盲眼老者说，「记得往远处传。不一定要收徒——你把活做正了，看着的人自然学。」",options:[{label:"「敬艺二字，受教了。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"看盲眼老者带徒一下午，学会「骂是疼」的道理"},text_after:"「能传多久？」盲眼老者想了想，「看天。可我告诉你我的算法：只要还有人肯为一个细节较真——这门手艺就活着。你今天盯着我这活看了半晌，就在较真。所以今天，它又多活了一天。」"}},{label:"「与我何干，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」盲眼老者不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g621_haiyuan:{id:"adv_g621_haiyuan",title:"劫峰里替故人还愿的中年汉子",mother:"M4",channel:"T1",rarity:3,entry:{node:"pl_jiefeng",chance:.05},stages:[{xinglu:"是岁劫峰逢中年汉子。中年汉子的话糙，理却直——「替人还愿这行，赚的不是钱——是夜里睡得着。」",text:"中年汉子在劫峰打听路，手里攥着一件没织完的衣裳——他在替谁了却一桩心愿。「这是我欠他的。」中年汉子说，「当年他有难处，我没能帮上。如今他走了，我把他的愿当我的债——债这东西，躲一辈子，不如还一趟。」「客人赶路，可否捎我一段？」中年汉子诚恳道，「多个人说话，路就不显得长——我讲给你听，这愿是个什么愿。」",options:[{label:"「我听过，说与你听。」",goto:1,effect:void 0},{label:"「人都没了，何必呢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「与我无关？」中年汉子也不恼，「是啊，天下事都与谁无关呢？他跟我无关的时候，我欠了他一辈子。你走吧——愿你一辈子都用不上替人还愿。用不上，是福气。」"}}]},{xinglu:"是岁劫峰一课。中年汉子把话说到根上——「故人最大的悲哀不是死——是心愿烂在没人知道的地方。」",text:"「你还愿还出过蹊跷事没有？」中年汉子忽然问你，「我遇到过一回——你说邪门不邪门。」「讲一个还愿的故事：有个老猎户，临终托我把他攒的一袋盐分给当年一起守山的弟兄。」中年汉子说，「弟兄散了，我找了四年，七个找到了六个。第七个，去年在狱里寻着——他犯了事。我把盐给他，他捧着哭了半宿，说：哥几个还记着我。出狱那天，他来找我，如今在山上替人守林。你说，一袋盐值什么？可有些时候，一袋盐就是把人从沟里拉上来的绳。」「你要是记得今天这故事，」中年汉子说，「往后见着满头白发的还愿人，别笑他痴。给他一碗水——他替这世上所有走了的人，捎着话呢。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"捎中年汉子一程，听了一个还愿人的故事"},text_after:"「尽到心没尽到心，我自己知道。」中年汉子摇头，「可你说这话，我路上就不孤单了。还愿人最怕的不是路——是没人说一句『够了，可以了』。你说了一句。我记下了。」"}},{label:"「这故事听着累。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」中年汉子笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g622_zengxing:{id:"adv_g622_zengxing",title:"妖渊上层渔场的一课：妇人白送路上的东西",mother:"M1",channel:"T2",rarity:1,entry:{node:"yy_shangceng",chance:.12},stages:[{xinglu:"是岁妖渊上层渔场逢妇人。妇人的话糙，理却直——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"你打妖渊上层渔场过，妇人招呼你：「歇歇脚？不要钱，也别推——推就见外了。」「你仔细看我的木牌。」妇人指给你，「写的是『自取』，不是『施与』。一字之差——拿的人心里就平了。善这个东西，得把人的脸面一起护住才算善。」「客人腿脚快，是赶远路的？」妇人问完不等答，已经把东西包好了，「远路更要带——不是干粮，是个念想。」",options:[{label:"「往后还走。」",goto:1,effect:void 0},{label:"「我不占人便宜。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」妇人愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁妖渊上层渔场一课。妇人把话说到根上——「路上的东西谁都需要，路上的心谁都不肯先给——我先给。」",text:"「有一年冬天，来了个贼。」妇人说起这事，倒像说旁人。「起头真是给自己备的。」妇人坦白道，「那年我落魄，怕自己哪天走投无路，就先备着——备着备着，先被人用了。用的人跟我说谢，我脸上臊——原来我备下的东西，早有人比我更需要。从那天起，这就不是我的退路了，是路上的公物。」「记住这条道的规矩。」妇人指指一篮挂在枝头的果子，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"义",text:"在妖渊上层渔场白得一份干粮，后来也学着挂了一壶茶"},text_after:"你记住了那条规矩。后来你真在道上遇着同样的摊子，取的时候留了双份的钱压在木牌下。摊主追出来还钱，你说：「前头妖渊上层渔场有位老丈教的——够用就行，多留是给后头的。」摊主愣了愣，朝你作了个揖。那一刻你忽然明白：妇人的账本，原来一直记到你身上。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」妇人点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一篮挂在枝头的果子，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]},adv_g623_shouye:{id:"adv_g623_shouye",title:"路遇少年——在妖域水域夜里替人醒着",mother:"M2",channel:"T3",rarity:1,entry:{node:"yy_zhongceng",chance:.07},stages:[{xinglu:"是岁妖域水域逢少年。少年的话糙，理却直——「守夜不图别的——图鸡叫的时候，家家还都是囫囵的。」",text:"少年守在一条巷子的更道旁，火光把他的影子拉得很长，见你近前，先问了句：「夜里赶路，有事？」「守夜人最要紧的不是胆，是觉浅。」少年笑道，「风吹草动，我在三里外的被窝里都能竖起耳朵。这不是本事——这是把心搁在妖域水域搁了二十年，搁熟了。」「夜里的事，你遇上过么？」少年问你，「遇上过就知道我这盏灯的用处了。」",options:[{label:"「有您这句保票，我睡了。」",goto:1,effect:void 0},{label:"「半夜不睡，有病吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「认得黑路是好事。」少年没拦你，「可你认得的是路——路认不认你，两说。去年有个自认得路的，掉进了拆了半截的桥坑里，躺了一夜——他不知道那坑，我知道。」他举灯照了照那个方向，「喏，就那儿。坑还在，天亮我得上报。」你没再犟，跟着他走了那条亮路。"}}]},{xinglu:"是岁妖域水域一课。少年把话说到根上——「夜不怕黑——夜怕的是没人醒着。」",text:"「白天的官府管不了的，夜里都得有人管。」少年说，「你猜夜里都有什么事？」「夜里的事，是病人、是醉汉、是走投无路的人。」少年一样样数给你听，「产妇半夜要生，是我跑去接的稳婆；醉汉躺在冰边上，是我拖回来的；还有个后生想跳河——我在河边陪他坐到天亮，一句话没劝，他就自己回去了。」少年叹口气，「白天的人都以为夜里干净。夜里最不干净——夜里的难处，都是白天咽下去的。」「天快亮了。」少年打了个梆，「五更，天下太平。你听——鸡都叫了。这就是守夜人的一天：什么都没发生，就是最大的事。」",options:[{label:"「这话我懂了。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"受少年夜路相送一程，妖域水域三里无事故"},text_after:"天亮了。你按少年教的走了那条新路——果然避开了塌方段。回头望，少年已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜妖域水域的太平，全是这根梆子敲出来的。"}},{label:"「你这灯，照不了多远。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」少年指指自己的眼睛，「我这双眼二十年没睡过一个整觉——妖域水域每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g624_shiyi:{id:"adv_g624_shiyi",title:"南天门的一课：盲眼老者替失物寻主人",mother:"M6",channel:"T1",rarity:2,entry:{node:"xj_nantianmen",chance:.07},stages:[{xinglu:"是岁南天门逢盲眼老者。盲眼老者的话糙，理却直——「我守着一屋子没人要的东西，其实守着一屋子没人讲完的故事。」",text:"南天门里，盲眼老者守着一屋一篮子从河里捞起的东西，见你进来，先问一句：「客人丢过什么？」「我这册子记了二十年。」盲眼老者翻着一篮子从河里捞起的东西边的旧簿，「每件失物什么样子、哪儿捡的、像是谁丢的——都记着。册子比我的脑子靠得住。人的记忆会骗人，字不会。」盲眼老者递给你一件失物：「你摸摸。摸完了你说说，它的主人是个什么样的人？」",options:[{label:"「找到主人要紧。」",goto:1,effect:void 0},{label:"「失物还想着领？痴人。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人？」盲眼老者摇头，「你丢了东西就知道了——丢东西的人，个个都是痴人。我见过丢了亡妻一支簪子的铁塔似的汉子，在我这儿哭成泪人。你笑痴——那是你的福气。真到了痴那天，你盼着世上多几个痴人。」他把门为你拉开，「慢走。愿你一辈子用不上我这行。」"}}]},{xinglu:"是岁南天门一课。盲眼老者把话说到根上——「丢东西的人分两种：丢得起的一笑了之，丢不起的——那种你得跑断腿。」",text:"「拾遗这行，也有发懵的时候。」盲眼老者说，「讲一件，你听听值不值。」「那件一文不值的，是半只风筝。」盲眼老者从柜里捧出来，「碎得没法再飞了。是个娃丢的——他爹重病，他放了一天风筝，说放完了爹就好了。爹没好，走了。风筝也丢了。」盲眼老者声音低下去，「我找了他四年。找到时那娃已经不哭了，只说了句：叔叔，风筝回来了，是不是爹也记得回来？我答不上来。我把风筝给他，他把他爹留的一枚旧扣子给我——说换。我没推。我库里的东西，就数这件最贵。」「东西你拿走一件。」盲眼老者忽然说，「不是送你——是托你。你走到别处，替它问问它的主人。我守在这儿出不去，你的腿比我的长。」",options:[{label:"「这行当，敬您一声。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"义",text:"一眼认出包袱上的字迹，省了盲眼老者三个月的腿"},text_after:"「找主人要紧。」盲眼老者点头，「可你方才那个问法好——问的是主人放下了没有。这些年我只顾找，忘了问这个。有的失物，主人早放下了，是我攥着不放。」他笑了，「所以你看，问路的功劳不在答——在问。你今天这一问，我这行当又多了一条规矩。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人就痴人。」盲眼老者坦然得很，「这世上总得有人痴——都精明着，丢的东西就真没了。你精明你的，我痴我的。哪天你精明不动了、累了，我这一屋子痴，兴许还能给你焐焐手。」"}}]}]},adv_g625_wenlu:{id:"adv_g625_wenlu",title:"天庭衙署里只问不答的中年汉子",mother:"M7",channel:"T2",rarity:2,entry:{node:"xj_yashu",chance:.11},stages:[{xinglu:"是岁天庭衙署逢中年汉子。中年汉子的话糙，理却直——「问句是钩子——鱼上不上钩不要紧，水被搅活了就行。」",text:"中年汉子正把新写的问题挂上一只装满纸条的竹筒：「客人看看，这个问题值得挂么？」「你说人为什么要问路？」中年汉子自问自答，「因为路认生。认生的东西，你不问它，它就骗你——这是路教的，我只是转述。」「我考考你。」中年汉子眼睛一亮，「就一个问题——答上来，我这一只装满纸条的竹筒上的问题随你挑一个带走。」",options:[{label:"「您考我。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我答？」中年汉子摊开手，「我要是答得上，还开店做什么？」他指指一只装满纸条的竹筒，「你看这满墙的问题——我答上的不到十个。剩下的，都是别人答的、路教的、年头给的。我这不是卖关子——我是个替人传话的，传天地的、传岁月的、传你自己心里的。你急着要我答，就像问镜子要路——路在你脚下，不在镜子里。」"}}]},{xinglu:"是岁天庭衙署一课。中年汉子把话说到根上——「问不丢人——不懂装懂才丢人。」",text:"「有人骂我，说问了半天屁用没有。」中年汉子居然点头，「他骂得对。你听听怎么回事。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」中年汉子缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」中年汉子笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」「客人慢走。」中年汉子拱手，「你今天答了我好几个问题——答得对不对不要紧，你认真想了。认真想的人，走哪儿都带着先生。这先生就是你自己的那颗心——别偷懒使唤它。」",options:[{label:"「先生二字，您当得起。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"在中年汉子店里吵了一架，各自往前挪了半步"},text_after:"你收下那个问题，揣了三年。第三年秋天你在异乡的田埂上想通了——回去时中年汉子的店还开着，你把答案丢进竹筒。后来听说他每逢初一就摇竹筒听响，笑着说：「这条又满了。」你不知道他说的哪条是你——可你知道，有个人的问题，替你养了三年的心。"}},{label:"「故弄玄虚，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」中年汉子把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g626_jizhang:{id:"adv_g626_jizhang",title:"瑶池里替人情记着账的清瘦老者",mother:"M8",channel:"T3",rarity:2,entry:{node:"xj_yaochi",chance:.11},stages:[{xinglu:"是岁瑶池逢清瘦老者。清瘦老者的话糙，理却直——「我记的不是债——是这世上「有人还过」的证据。」",text:"清瘦老者正给一户人家抄账——抄完把原册还人家，抄本自己留：「一式两份，两头作数。」「有人问我，死人欠的账记来做什么。」清瘦老者说，「记。儿子长大来翻账——看见他爹当年受过谁的恩、还过谁的债，他就知道自己是个什么根底。账本就是家谱，还是最老实的那一页。」清瘦老者递给你一盏茶：「先别急着走。听我说说这账本上的头一页——听完你就知道，账不是冰的。」",options:[{label:"「先记欠的。」",goto:1,effect:void 0},{label:"「你这行当，多管闲事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过去？」清瘦老者摇头，「过得去的才叫过去。过不去的，你不理它，它就长在心里长成疙瘩。我这柜子里的账，一半是让人过得去的——账面摆出来，多少年的疙瘩，一句话就解了。」"}}]},{xinglu:"是岁瑶池一课。清瘦老者把话说到根上——「一笔账两头记——欠的人记着还，还的人记着情，两头都记着，人就亲了。」",text:"「你见过两家人为一笔账断了二十年的来往么？」清瘦老者说，「我接手过。」「最恨我的是人贩子。」清瘦老者冷冷道，「他们拐走的孩子，我账上都有底——哪家孩子哪年生、什么胎记、谁抱走的。他们烧过我的铺子，砍过我的门。可账在人心里的那份，他们烧不掉——街上人人替我记着。」清瘦老者把柜子锁好，「我这账本为什么比官府的册子灵？因为官府的册子锁在库里，我的账——长在几千户人的嘴里。」「我这行干到死。」清瘦老者说，「死了我这账传给徒弟——徒弟再传徒弟。账本不怕旧，就怕断。你哪天路过，看看它还开着门不——开着，就说明有人接着记呢。」",options:[{label:"「这碗茶，敬记账人。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"在瑶池受清瘦老者一句账理：欠的记着，还的记着"},text_after:"你把那句话带走了。后来你受了人的恩，总会想起那笔「不欠谁的」的账——想起时脸就发热，热完了就认真去还。再后来你也学着记：谁帮过你、你欠过谁，一笔一笔记在心里。你还真把这些教给了你的孩子——账本没传下去，账理传下去了。"}},{label:"「记账记成痴，何苦。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」清瘦老者笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g627_shouwu:{id:"adv_g627_shouwu",title:"魔渊的一课：驼背阿婆守着一件旧物",mother:"M5",channel:"T1",rarity:1,entry:{node:"xj_moyuan",chance:.09},stages:[{xinglu:"是岁魔渊逢驼背阿婆。驼背阿婆的话糙，理却直——「东西没了可以再造，守的规矩断了就接不上。」",text:"你还没开口，驼背阿婆先给你讲了一杆褪色的大旗的故事——讲得像讲自家孩子。「它在这儿站了几十年，看过的路人数都数不清。」驼背阿婆拍拍一杆褪色的大旗，「东西不嫌人多——就嫌人忘。你多看它两眼，它就不算白站。」驼背阿婆从怀里摸出个小本子：「守物的账。你帮我记一笔——今天有人来看过它。这一笔，比我给你什么都强。」",options:[{label:"「有什么我能搭手的？」",goto:1,effect:void 0},{label:"「破烂一个，守它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"你绕着走了。走出去老远，风里飘来一句话似的调子——驼背阿婆在给一杆褪色的大旗哼曲儿。你忽然明白：人家守得高兴，根本不在乎你看不看。这么一想，你的脚步倒轻快了。"}}]},{xinglu:"是岁魔渊一课。驼背阿婆把话说到根上——「守物的规矩只有一条：别让它在你手里断。」",text:"驼背阿婆坐下来，给你讲了件旧事——讲完自己半天没言语。「那年水退了，一杆褪色的大旗还在，人也都在。」驼背阿婆说，「从那以后我就明白了——你守着它，它就替你守着这一片的人心。」「我把本子给你看看就懂了。」驼背阿婆翻开守物账——密密麻麻全是名字，「这些人都来看过它。你今天也来过——这账，会一直记下去。」",options:[{label:"「替它谢谢您。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"恩",text:"帮驼背阿婆修缮一杆褪色的大旗，魔渊的旧物得以长存"},text_after:"「它听见了。」驼背阿婆把本子合上，「往后它记你一笔。你别不当真——东西的账比人的账久。人忘了，它身上那道擦亮的印子忘不了。」"}},{label:"「天下旧物多了，管不过来。」",end:!0,effect:{stat:{wuxing:1},text_after:"驼背阿婆也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g628_chuanyi:{id:"adv_g628_chuanyi",title:"幽冥来了个把手艺往下传的盲眼老者",mother:"M3",channel:"T2",rarity:2,entry:{node:"xj_youming",chance:.09},stages:[{xinglu:"是岁幽冥逢盲眼老者。盲眼老者的话糙，理却直——「我把一辈子拆成手艺，你拿去接着活。」",text:"盲眼老者正用一面祖传的皮影示范，做坏了，当着徒弟的面拆了重来：「错不藏——藏了错，就传了错。」「手艺这行，学三年，学的是不怕烦。」盲眼老者拿起一面祖传的皮影给你比划，「你怕烦，活就糊弄你；你不怕烦，活就给你撑场面。」「你要是感兴趣，我讲细点。」盲眼老者说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"「说实话——这是真功夫。」",goto:1,effect:void 0},{label:"「这些老规矩，过时了。」",end:!0,effect:{stat:{wuxing:1},text_after:"你没搭理就走了。盲眼老者也没留你，只在你背后继续教徒弟。可那句「错不藏」追了你半条街——你想起自己上回做错事推了个干净，脚步忽然就沉了。"}}]},{xinglu:"是岁幽冥一课。盲眼老者把话说到根上——「手艺不传，人就白活一遭。」",text:"「手艺里最难的，不是教会的，是教不会的。」盲眼老者看着你，「你听我讲讲教不会的那部分。」「成器的那个，如今在外头独当一面；走了样的那三个，拿了手艺去糊弄人。」盲眼老者说，「我记牢的是骂我最狠的那个——他嫌我严，走了。前年他回来磕头，说在外头吃了不懂规矩的亏。我没怪他——他这一圈弯路，就是他没听完的课。」「我这一面祖传的皮影，早晚传给肯下苦功的人。」盲眼老者望着作坊，「也许是我徒弟，也许是徒弟的徒弟，也许——是个今天来歇脚的路人。缘分这东西说不准。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"义",text:"在幽冥受盲眼老者一课，悟「敬艺」之理"},text_after:"「能传多久？」盲眼老者想了想，「看天。可我告诉你我的算法：只要还有人肯为一个细节较真——这门手艺就活着。你今天盯着我这活看了半晌，就在较真。所以今天，它又多活了一天。」"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」盲眼老者不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g629_haiyuan:{id:"adv_g629_haiyuan",title:"路遇妇人——在轮回井替故人还愿",mother:"M4",channel:"T3",rarity:1,entry:{node:"xj_lunhui",chance:.09},stages:[{xinglu:"是岁轮回井逢妇人。妇人的话糙，理却直——「还愿的人不问值不值——问值不值的时候，愿就已经不是愿了。」",text:"妇人在轮回井打听路，手里攥着一份没还清的人情——他在替谁了却一桩心愿。「家里人劝我，人走了就放下。」妇人摇头，「放下是给活人的宽心话。可愿不是包袱——愿是路标。我把这个愿还了，往后他坟头的草，我看着都顺眼。」「客人赶路，可否捎我一段？」妇人诚恳道，「多个人说话，路就不显得长——我讲给你听，这愿是个什么愿。」",options:[{label:"「我听过，说与你听。」",goto:1,effect:void 0},{label:"「故人的东西，留着何用。」",end:!0,effect:{stat:{wuxing:1},text_after:"「路远事烦？」妇人笑了，「路是死的，事是活的。你嫌烦的事，兴许正是别人临终攥着的念想。我不怪你——年轻时我也这么想。就当我今天这些话，是说给二十岁的我听的。」你脸上一热，他已转身走远。"}}]},{xinglu:"是岁轮回井一课。妇人把话说到根上——「一个愿就是一条路，替人走路的，自己也有路走。」",text:"「说起这个愿的来历，」妇人坐下身来，「得从头讲。」「蹊跷事是这样的：那年到地方，收信的人家早搬了。」妇人说，「我打听三个月，问遍十里八乡——就在我要走的前一天，一个后生找上门：我是他孙子，爷爷临终说，会有人送东西来。」妇人摊开手，「你说，愿认路，还是我认路？我不知道。我只知道，愿不能停在半道。」妇人把一小撮路上的干粮分给你：「同行一程，就是有缘。这个你拿着——路上的人情，也是愿的一部分。我替故人结的善缘，多一个是一个。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"义",text:"为妇人的故人之愿指了路，了却半桩心愿"},text_after:"你帮着辨出了那页纸上的字——缺的那一角，是收信人的名字。妇人盯着那个名字看了许久：「对上了。就差这个字，我在县里翻了三天的户籍。」他抬头时眼眶红了，「客人，你今天不是帮我看字——你是替他把最后一句话，送到了门口。」"}},{label:"「我帮不上，别缠着我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「帮不上不打紧。」妇人摆摆手，「别缠着我——这话就伤人了。我讨的不是你的帮，是你让一步路。让一步路，天塌不下来。」他让到道旁，先请你走。你从他身边过的时候，忽然觉得这一步，让得自己心里发虚。"}}]}]},adv_g630_zengxing:{id:"adv_g630_zengxing",title:"路遇清瘦老者——在天外混沌白送路上的东西",mother:"M1",channel:"T1",rarity:2,entry:{node:"xj_hundun",chance:.06},stages:[{xinglu:"是岁天外混沌逢清瘦老者。清瘦老者的话糙，理却直——「东西有价，搭把手没价。」",text:"清瘦老者在天外混沌支着一垛谁都可取的干草，有人取用，他连头都不抬，只说慢用。「这东西损耗大，我不是不心疼。」清瘦老者笑了，「可我算过另一笔账：一年三百六十五天，总有那么几天，正是有人最需要它的时候。我囤的不是货——是那几天的『正好』。」「你给我评评，」清瘦老者指着木牌，「这两个字哪个当头好——『自取』还是『共济』？我想了半年了。」",options:[{label:"「您这摊子，摆了几年？」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不占便宜是好品性。」清瘦老者点头，「可我这不叫便宜——叫过路钱。你今天不喝我这口，往后你发达了在别处摆摊，让人白喝——这账就平了。」他硬塞给你，「路上没有白拿，只有先拿后还。你先欠着，我说这话不臊——你将来还得起。」"}}]},{xinglu:"是岁天外混沌一课。清瘦老者把话说到根上——「白给的东西要正大光明地白给——藏着掖着，善就变了味。」",text:"「有人劝我立个碑，写上善人某某。」清瘦老者摇头，「你听听我为什么不立。」「得意的是那边——」清瘦老者指的远处有户人家，「那家两口子，当年落难，在我这儿白吃了半个月。后来缓过来了，在自家村口也摆了一摊。再后来，那条道上每隔十里就有一摊——不是我摆的。我这一缸茶，泡出了一条道的人心。你说值不值？」「我老了，这摊子早晚交出去。」清瘦老者望着路，「交给谁？交给先坐下来的那个人。谁肯坐下来陪它过日子，它就是谁的。你哪天路过歇脚——兴许就是你。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"义",text:"受清瘦老者所托，允诺传递路边的规矩"},text_after:"你记住了那条规矩。后来你真在道上遇着同样的摊子，取的时候留了双份的钱压在木牌下。摊主追出来还钱，你说：「前头天外混沌有位老丈教的——够用就行，多留是给后头的。」摊主愣了愣，朝你作了个揖。那一刻你忽然明白：清瘦老者的账本，原来一直记到你身上。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」清瘦老者居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一垛谁都可取的干草像一方小小的印，盖在漫长的路上。"}}]}]}};Object.assign(e,t);export{t as ADVENTURES23};
